/* Estimate Pro — Help / tutorial page (English + हिंदी), shown as the "Help" tab for every user */
(function () {
  "use strict";
  var EP = window.EP, S = EP.S, U = EP.ui;
  function lang() { try { return localStorage.getItem("ep_help_lang") || "hi"; } catch (e) { return "hi"; } }
  function setLang(l) { try { localStorage.setItem("ep_help_lang", l); } catch (e) {} }
  S.help = { lang: lang() };
  function img(f, en, hi) { return { img: f, cap: { en: en, hi: hi } }; }

  /* Each section: id, title {en, hi}, blocks: html strings {en, hi} or images */
  var SEC = [
    { id: "start", t: { en: "1. Getting started", hi: "1. शुरुआत कैसे करें" }, b: [
      { en: "<p>Open the website and click <b>Start free trial</b> or <b>Sign in</b>. You can sign in with <b>Google</b> or with your <b>email and password</b>.</p><ul><li><b>New account:</b> click <i>Create an account</i>, enter your name, email and a password (8+ characters), then click the link in the confirmation email.</li><li><b>Forgot password:</b> click <i>Forgot password?</i> and follow the email link.</li><li><b>One computer at a time:</b> signing in on a new computer signs you out on the old one. This protects your account.</li></ul>",
        hi: "<p>वेबसाइट खोलें और <b>Start free trial</b> या <b>Sign in</b> पर क्लिक करें। आप <b>Google</b> से या <b>ईमेल-पासवर्ड</b> से लॉगिन कर सकते हैं।</p><ul><li><b>नया अकाउंट:</b> <i>Create an account</i> दबाएँ, नाम, ईमेल और पासवर्ड (कम से कम 8 अक्षर) भरें, फिर ईमेल में आए लिंक पर क्लिक करें।</li><li><b>पासवर्ड भूल गए:</b> <i>Forgot password?</i> दबाएँ और ईमेल के लिंक से नया पासवर्ड बनाएँ।</li><li><b>एक समय में एक कंप्यूटर:</b> नए कंप्यूटर पर लॉगिन करते ही पुराने कंप्यूटर से अपने-आप लॉगआउट हो जाता है। इससे आपका अकाउंट सुरक्षित रहता है।</li></ul>" },
      img("01-signin.png", "Sign-in page: Google or email", "साइन-इन पेज: Google या ईमेल से"),
      { en: "<p><b>Free trial:</b> every new account can use everything for 7 days. A banner shows the days left. After the trial you can still open and export your estimates, but to create or change anything, contact sales to activate your account.</p>",
        hi: "<p><b>फ्री ट्रायल:</b> हर नए अकाउंट को 7 दिन तक सभी सुविधाएँ मिलती हैं। ऊपर बैनर में बचे हुए दिन दिखते हैं। ट्रायल के बाद भी आप अपने एस्टीमेट खोल और Excel में निकाल सकते हैं, लेकिन नया बनाने या बदलने के लिए sales से संपर्क करके अकाउंट activate कराएँ।</p>" },
      img("02-trial.png", "Trial banner with days left and sales contact", "ट्रायल बैनर: बचे दिन और sales संपर्क"),
      img("03-expired.png", "After the trial: view and export only until activated", "ट्रायल के बाद: activate होने तक केवल देखना और export"),
    ] },
    { id: "projects", t: { en: "2. Projects (estimates)", hi: "2. प्रोजेक्ट (एस्टीमेट)" }, b: [
      { en: "<p>The bar at the top of the <b>Estimates</b> tab shows your projects.</p><ul><li><b>+ New estimate:</b> type a name and click <i>Create</i>. Your saved header and signatures are filled in automatically.</li><li><b>Project dropdown:</b> click the project name to see all projects with items and total; type to search.</li><li><b>Example:</b> on a new account, <i>Create example</i> makes a two-part sample estimate you can study.</li><li>Everything saves automatically (“Saved” appears next to the project name).</li></ul>",
        hi: "<p><b>Estimates</b> टैब में सबसे ऊपर की पट्टी में आपके प्रोजेक्ट दिखते हैं।</p><ul><li><b>+ New estimate:</b> नाम लिखें और <i>Create</i> दबाएँ। आपका सेव किया हुआ header और signature अपने-आप भर जाता है।</li><li><b>Project dropdown:</b> प्रोजेक्ट के नाम पर क्लिक करें — सभी प्रोजेक्ट, उनके items और total दिखेंगे; ऊपर लिखकर खोजें।</li><li><b>Example:</b> नए अकाउंट में <i>Create example</i> से दो Part वाला नमूना एस्टीमेट बनता है, जिसे देखकर सीख सकते हैं।</li><li>सब कुछ अपने-आप सेव होता है (प्रोजेक्ट नाम के पास “Saved” दिखता है)।</li></ul>" },
      img("04-new-project.png", "Creating a new estimate", "नया एस्टीमेट बनाना"),
      img("05-project-picker.png", "Project dropdown with search", "खोज के साथ प्रोजेक्ट ड्रॉपडाउन"),
      { en: "<p><b>Copy estimate:</b> to reuse an old estimate, open it and click <b>Copy estimate</b>. Give a new name and choose whether to keep quantities/measurements and the name of work. Parts, items, NS analyses, header and GST are copied.</p>",
        hi: "<p><b>Copy estimate:</b> पुराने एस्टीमेट को दोबारा इस्तेमाल करना हो तो उसे खोलें और <b>Copy estimate</b> दबाएँ। नया नाम दें और चुनें कि quantity/measurement और Name of work रखना है या नहीं। Parts, items, NS analysis, header और GST सब कॉपी हो जाते हैं।</p>" },
      img("15-copy.png", "Copy an estimate", "एस्टीमेट कॉपी करना"),
    ] },
    { id: "items", t: { en: "3. Adding items (SOR)", hi: "3. आइटम जोड़ना (SOR)" }, b: [
      { en: "<p>In <b>Items &amp; measurement</b>, choose the part (Part A, Part B… — use <i>+ Add part</i> for more), then type in the search box:</p><ul><li>a <b>code</b> (6.34.2, 4.1.3, 12.1) or <b>words</b> (vitrified tiles, wet mix macadam);</li><li><b>site words</b> also work: gitti, sariya, khudai, dhalai, putai, pcc, rcc, wbm, gsb…; small spelling mistakes are forgiven;</li><li>pick a rate book in the dropdown to search only CPWD, MPPWD, Horticulture or your own SOR;</li><li>hover (or tap the <b>i</b>) to read the <b>full description</b>; click the row to add it. Clicking the empty box shows <b>recently used</b> items.</li></ul><p>Then type the <b>Qty</b> directly, or click <b>Measure</b> to build it from measurements.</p>",
        hi: "<p><b>Items &amp; measurement</b> में Part चुनें (Part A, Part B… — और Part के लिए <i>+ Add part</i>), फिर search box में लिखें:</p><ul><li><b>कोड</b> (6.34.2, 4.1.3, 12.1) या <b>शब्द</b> (vitrified tiles, wet mix macadam);</li><li><b>साइट के शब्द</b> भी चलते हैं: गिट्टी (gitti), सरिया (sariya), खुदाई (khudai), ढलाई (dhalai), पुताई (putai), pcc, rcc, wbm, gsb…; छोटी स्पेलिंग गलती भी चल जाती है;</li><li>ड्रॉपडाउन से केवल CPWD, MPPWD, Horticulture या अपनी SOR में खोजें;</li><li>रिज़ल्ट पर माउस रखें (या <b>i</b> दबाएँ) तो <b>पूरा description</b> दिखता है; row पर क्लिक करके आइटम जोड़ें। खाली box पर क्लिक करने से <b>हाल में उपयोग किए</b> आइटम दिखते हैं।</li></ul><p>फिर <b>Qty</b> सीधे लिखें, या <b>Measure</b> दबाकर नाप से quantity बनाएँ।</p>" },
      img("07-search.png", "Search with full-description popup", "पूरा description दिखाने वाला सर्च"),
      img("06-items.png", "Items table: SOR rate, updated rate and amounts", "आइटम टेबल: SOR रेट, updated रेट और राशि"),
      { en: "<p><b>Suggested items by work type:</b> click <i>Browse by work type</i> (or the <i>Suggested items</i> tab). Pick a work type — buildings, roads (BT, CC, WBM, colony/paver, road safety, repairs), drains and culverts, excavation, site development, dust suppression, garden, decoration, interior, exterior, carpentry, cladding, wall panelling. The usual items are grouped stage by stage (earthwork → foundation → superstructure → finishing). Tick single items or a whole stage, choose the part and click <b>Add selected</b>. Items marked <b>NS</b> are not in any SOR and come in as non-SOR items for a market rate or analysis. Items already in the part are not added twice.</p><p><b>Schedule:</b> first choose <i>DSOR 2023</i> or <i>DSR 2021</i> at the top — the CPWD items switch to that schedule. Also included: <b>Mines &amp; coalfield works</b> (hire of PC-210 / PC-300 excavators, dozer, grader, tipper, water tanker, labour supply, drinking water by tanker, haul roads) and <b>Retaining &amp; protection works</b> (retaining wall, gabion wall). NS items marked <i>rate analysis ready</i> come with a machine / labour analysis on DAR 2023 rates — enter your local hire quotation where the rate is blank.</p>",
        hi: "<p><b>काम के प्रकार से सुझाए गए आइटम:</b> <i>Browse by work type</i> (या <i>Suggested items</i> टैब) दबाएँ। काम का प्रकार चुनें — भवन, सड़कें (डामर, सीसी, WBM, कॉलोनी/पेवर, सड़क सुरक्षा, मरम्मत), नाली और पुलिया, खुदाई, साइट विकास, धूल नियंत्रण (dust suppression), उद्यान, सजावट, इंटीरियर, एक्सटीरियर, बढ़ईगीरी, क्लैडिंग, वॉल पैनलिंग। आम आइटम चरण-वार (खुदाई → नींव → ढाँचा → फिनिशिंग) दिखते हैं। एक-एक आइटम या पूरा चरण टिक करें, Part चुनें और <b>Add selected</b> दबाएँ। <b>NS</b> वाले आइटम किसी SOR में नहीं हैं — वे नॉन-SOR आइटम बनकर आते हैं, जिनका रेट market या analysis से भरें। जो आइटम पहले से Part में है, वह दोबारा नहीं जुड़ता।</p><p><b>Schedule:</b> ऊपर पहले <i>DSOR 2023</i> या <i>DSR 2021</i> चुनें — CPWD आइटम उसी SOR के आ जाएँगे। इसमें <b>खदान / कोलफील्ड कार्य</b> (PC-210 / PC-300 पोकलेन, डोज़र, ग्रेडर, टिपर, पानी टैंकर का घंटे का किराया, मजदूर आपूर्ति, पेयजल टैंकर, हॉल रोड) और <b>रिटेनिंग / गेबियन वॉल</b> भी हैं। <i>rate analysis ready</i> वाले NS आइटम DAR 2023 रेट पर मशीन / लेबर analysis के साथ आते हैं — जहाँ रेट खाली है वहाँ अपना स्थानीय quotation डालें।</p>" },
      img("21-suggested.png", "Suggested items by work type — tick and add", "काम के प्रकार से सुझाए गए आइटम — टिक करें और जोड़ें"),
      { en: "<p><b>CPWD DSOR 2023:</b> the new schedule (Vol. 1 &amp; 2) with the full DAR 2023 rate analysis of each item (18% GST through factor 0.2127, 15% CPOH, 1% water, 1% cess). Pick it in the book dropdown, or search all books. DSR 2021 stays available for old estimates.</p><p><b>One item once per part:</b> the same SOR item can be added only once in a part (it can repeat in other parts). If you pick it again, the existing item opens — add more measurement rows there.</p><p><b>SOR rate vs updated rate:</b> the SOR rate is the printed rate of the book. The updated rate comes from the rate analysis with current basic rates (or an entered rate). Both totals are shown, and the abstract shows both.</p>",
        hi: "<p><b>CPWD DSOR 2023:</b> नई SOR (Vol. 1 और 2) — हर आइटम का पूरा DAR 2023 rate analysis (18% GST factor 0.2127 से, 15% CPOH, 1% water, 1% cess)। Book dropdown में चुनें या सभी books में खोजें। पुराने एस्टीमेट के लिए DSR 2021 भी उपलब्ध है।</p><p><b>एक Part में एक आइटम एक ही बार:</b> एक ही SOR आइटम किसी Part में केवल एक बार जुड़ेगा (दूसरे Part में फिर से जुड़ सकता है)। दोबारा चुनने पर पहले वाला आइटम खुल जाता है — उसी में नाप की rows जोड़ें।</p><p><b>SOR रेट और updated रेट:</b> SOR रेट किताब में छपा रेट है। Updated रेट आज के basic rates से rate analysis द्वारा बनता है (या आपके डाले रेट से)। दोनों का total दिखता है और abstract में भी दोनों आते हैं।</p>" },
    ] },
    { id: "measure", t: { en: "4. Measurement sheet", hi: "4. मेज़रमेंट शीट (नाप)" }, b: [
      { en: "<p>Click <b>Measure</b> on an item. Each row is <b>No. × L × B × D × Factor</b>. You can type 15x45 or 2*3.5 in any box.</p><ul><li><b>+ Row</b> adds, <b>+ Deduction</b> subtracts (doors, windows, openings).</li><li><b>+ Heading</b> for a title (it can have sizes too).</li><li><b>+ Sub-total</b> totals the rows above; <b>+ Net total</b> gives additions − deductions of a block. They do not change the item quantity.</li><li><b>+ Add qty of another item / − Deduct qty of another item:</b> e.g. plaster area less tile area, or shuttering same as concrete × factor.</li><li>The line at the bottom shows <b>Additions − Deductions = Net quantity</b> used in the abstract.</li></ul>",
        hi: "<p>किसी आइटम पर <b>Measure</b> दबाएँ। हर row में <b>No. × L × B × D × Factor</b> होता है। किसी भी box में 15x45 या 2*3.5 लिख सकते हैं।</p><ul><li><b>+ Row</b> जोड़ता है, <b>+ Deduction</b> घटाता है (दरवाज़े, खिड़की, opening)।</li><li><b>+ Heading</b> शीर्षक के लिए (इसमें साइज़ भी डाल सकते हैं)।</li><li><b>+ Sub-total</b> ऊपर की rows का जोड़ देता है; <b>+ Net total</b> किसी हिस्से का जोड़ − घटाव देता है। इनसे आइटम की कुल quantity नहीं बदलती।</li><li><b>+ Add qty of another item / − Deduct qty of another item:</b> जैसे plaster area में से tile area घटाना, या shuttering = concrete × factor।</li><li>नीचे की लाइन में <b>Additions − Deductions = Net quantity</b> दिखती है, जो abstract में जाती है।</li></ul>" },
      img("08-measurement.png", "Measurement with deductions", "घटाव (deduction) के साथ मेज़रमेंट"),
    ] },
    { id: "steel", t: { en: "5. Steel / reinforcement", hi: "5. स्टील / सरिया (Reinforcement)" }, b: [
      { en: "<p>In a steel item (kg / tonne), use:</p><ul><li><b>+ Steel bar (BBS row):</b> member, level (up to / above plinth), number of members, bar Ø, shape (straight, hooked, L-bent, cranked, stirrup, ring), length or size, and bars by count or spacing. The cutting length includes cover, hooks, bends and laps; weight is from IS 1786.</li><li><b>+ Steel by thumb rule:</b> % of a concrete item (slab 1%, beam 2%, column 2.5%, footing 0.8%) — for rough estimates only.</li><li><b>IS 456 check:</b> choose the concrete item and member to see steel % and kg/cum.</li><li><b>Plinth split:</b> for DSR 5.22 / 5.22A one click moves rows to the right item.</li><li>Steel grade, concrete grade, exposure, lap and cover are set in <b>Header, parts &amp; GST</b>.</li></ul>",
        hi: "<p>स्टील आइटम (kg / tonne) में:</p><ul><li><b>+ Steel bar (BBS row):</b> member, level (plinth तक / plinth के ऊपर), members की संख्या, सरिया Ø, shape (सीधा, hook, L-bend, crank, stirrup, ring), लंबाई या साइज़, और bars की संख्या या spacing। Cutting length में cover, hook, bend और lap अपने-आप जुड़ते हैं; वज़न IS 1786 से।</li><li><b>+ Steel by thumb rule:</b> किसी concrete आइटम का % (slab 1%, beam 2%, column 2.5%, footing 0.8%) — केवल अनुमान के लिए।</li><li><b>IS 456 check:</b> concrete आइटम और member चुनें — steel % और kg/cum दिखेगा।</li><li><b>Plinth split:</b> DSR 5.22 / 5.22A में एक क्लिक से rows सही आइटम में चली जाती हैं।</li><li>Steel grade, concrete grade, exposure, lap और cover <b>Header, parts &amp; GST</b> में सेट होते हैं।</li></ul>" },
      img("09-steel-bbs.png", "BBS rows with dia-wise summary and IS 456 check", "BBS rows, dia-wise सारांश और IS 456 check"),
    ] },
    { id: "ns", t: { en: "6. Non-SOR (NS) items and rate analysis", hi: "6. नॉन-SOR (NS) आइटम और रेट एनालिसिस" }, b: [
      { en: "<p>For an item not in any SOR, click <b>+ Non-SOR (NS) item</b> (or <i>Create NS item</i> in search). Write the description and unit, then click <b>Start analysis</b> (CPWD add-ons 1% + 15% + 1%, or MPPWD 10% + 10%). Add lines:</p><ul><li><b>Basic rate:</b> search cement, beldar, mason, aggregate… — the current rate is used.</li><li><b>SOR item:</b> use another item's rate as a line.</li><li><b>+ Machine / equipment (hourly):</b> hire rate per hour, day, 8-hour shift or month; wet hire (incl. fuel &amp; operator) or dry hire (+ fuel L/hour × diesel + operator); hours typed or worked out from <b>output per hour</b>, with efficiency and minimum hours.</li><li><b>+ Market rate / other line</b> with <b>Quotes</b>: enter 3 quotations; lowest or average is adopted, and a <i>Market rate justification</i> table prints in Excel.</li><li>Set <b>Analysis for (qty)</b> and rounding; the rate per unit is shown at the bottom.</li><li><b>Save to my NS library</b> to reuse the item in any estimate (it appears in search as <i>My NS</i>).</li></ul>",
        hi: "<p>जो आइटम किसी SOR में नहीं है, उसके लिए <b>+ Non-SOR (NS) item</b> दबाएँ (या search में <i>Create NS item</i>)। Description और unit लिखें, फिर <b>Start analysis</b> दबाएँ (CPWD add-ons 1% + 15% + 1%, या MPPWD 10% + 10%)। फिर lines जोड़ें:</p><ul><li><b>Basic rate:</b> cement, beldar, mason, aggregate… खोजें — आज का रेट लगता है।</li><li><b>SOR item:</b> किसी दूसरे आइटम का रेट line के रूप में।</li><li><b>+ Machine / equipment (hourly):</b> किराया प्रति घंटा, प्रति दिन, 8 घंटे की shift या प्रति माह; wet hire (ईंधन व ऑपरेटर सहित) या dry hire (+ डीज़ल L/घंटा × रेट + ऑपरेटर); घंटे सीधे लिखें या <b>प्रति घंटा output</b> से निकालें, efficiency और न्यूनतम घंटे के साथ।</li><li><b>+ Market rate / other line</b> और <b>Quotes</b>: 3 quotation डालें; सबसे कम या औसत रेट लगता है, और Excel में <i>Market rate justification</i> टेबल छपती है।</li><li><b>Analysis for (qty)</b> और rounding सेट करें; नीचे प्रति यूनिट रेट दिखता है।</li><li><b>Save to my NS library</b> से आइटम किसी भी एस्टीमेट में दोबारा उपयोग करें (search में <i>My NS</i> नाम से दिखेगा)।</li></ul>" },
      img("10-ns-analysis.png", "NS analysis: basic rates, quotations and a machine line", "NS एनालिसिस: basic rates, quotations और मशीन line"),
      { en: "<p><b>Make NS copy:</b> in any SOR item, this button copies the item with its full analysis and measurements into an NS item — change thickness, mix or material for a modified specification.</p>",
        hi: "<p><b>Make NS copy:</b> किसी भी SOR आइटम में यह बटन उस आइटम को पूरे analysis और measurement के साथ NS आइटम में कॉपी कर देता है — बदली हुई specification के लिए मोटाई, mix या material बदलें।</p>" },
      img("11-ns-copy.png", "Make NS copy from an SOR item", "SOR आइटम से NS copy बनाना"),
      { en: "<p><b>Ready analyses for suggested NS items:</b> every Non-SOR item in <i>Suggested items</i> (market items 2026, E&amp;M, mines, services – 308 items) comes with a full analysis: each material with its quantity and market rate, labour on CPWD DAR 2023 basic codes (so it follows your basic rates), machinery, and add-ons (water 1 %, GST factor, 15 % CP&amp;OH, 1 % cess). Edit any line or add quotations. For an older NS item with the same description a <b>Use the ready analysis</b> button appears. Tip: lowering the labour basic rates to local (Chhattisgarh) levels lowers all labour-heavy NS items together.</p>",
        hi: "<p><b>सुझाए गए NS आइटम का तैयार एनालिसिस:</b> Suggested items के हर Non-SOR आइटम (मार्केट 2026, E&amp;M, खदान, सर्विस – 308 आइटम) के साथ पूरा एनालिसिस आता है: हर सामग्री की मात्रा और बाज़ार दर, मज़दूरी CPWD DAR 2023 basic codes से (आपकी basic rates के साथ बदलती है), मशीन और add-ons। किसी भी line को बदलें या quotation जोड़ें। पुराने NS आइटम में वही विवरण हो तो <b>Use the ready analysis</b> बटन आता है। सुझाव: labour basic rate स्थानीय दर पर करने से सभी labour वाले NS आइटम एक साथ सस्ते हो जाते हैं।</p>" },
      img("30-ns-ready.png", "Ready analysis of a market item: materials, labour and add-ons", "मार्केट आइटम का तैयार एनालिसिस: सामग्री, मज़दूरी और add-ons"),
    ] },
    { id: "header", t: { en: "7. Header, parts, GST and settings", hi: "7. Header, Parts, GST और सेटिंग" }, b: [
      { en: "<ul><li><b>Header:</b> organisation, office, project and <b>Name of work</b> — printed on every Excel sheet.</li><li><b>Signatures:</b> three designations printed at the foot of each sheet. <i>Save as my default</i> reuses them for new estimates.</li><li><b>GST %</b> and whether the updated rate comes from the analysis or the SOR rate.</li><li><b>Parts:</b> rename or delete parts; each part gets its own abstract, and the general abstract adds them.</li><li><b>Reinforcement settings</b> for BBS rows.</li></ul>",
        hi: "<ul><li><b>Header:</b> संस्था, कार्यालय, प्रोजेक्ट और <b>Name of work</b> — हर Excel शीट पर छपता है।</li><li><b>Signatures:</b> तीन पदनाम, हर शीट के नीचे छपते हैं। <i>Save as my default</i> से ये नए एस्टीमेट में अपने-आप आते हैं।</li><li><b>GST %</b> और updated rate analysis से लेना है या SOR रेट से।</li><li><b>Parts:</b> नाम बदलें या हटाएँ; हर Part का अलग abstract बनता है और general abstract में सबका जोड़।</li><li>BBS rows के लिए <b>Reinforcement settings</b>।</li></ul>" },
      img("12-header.png", "Header, signatures, GST, parts and reinforcement settings", "Header, signature, GST, parts और reinforcement सेटिंग"),
    ] },
    { id: "abstract", t: { en: "8. Abstract and Excel export", hi: "8. Abstract और Excel एक्सपोर्ट" }, b: [
      { en: "<p><b>Abstract</b> shows each part with quantity, SOR rate, updated rate and amounts, then GST and grand total.</p><p><b>Export to Excel</b> downloads: Measurement, Analysis (updated rates), Abstract (one per part), General Abstract, <b>SOR &amp; Non-SOR summary</b> (totals of SOR and NS items, without and with GST) and BOQ — as one linked workbook or each sheet separately. Formulas are live, so the file can be checked and printed directly.</p>",
        hi: "<p><b>Abstract</b> में हर Part की quantity, SOR रेट, updated रेट और राशि, फिर GST और grand total दिखता है।</p><p><b>Export to Excel</b> से डाउनलोड करें: Measurement, Analysis (updated rates), Abstract (हर Part का), General Abstract, <b>SOR &amp; Non-SOR summary</b> (SOR और NS आइटम का अलग जोड़, GST के बिना और GST सहित) और BOQ — एक जुड़ी हुई workbook में या अलग-अलग शीट। Formulas चालू रहते हैं, इसलिए फ़ाइल सीधे जाँची और प्रिंट की जा सकती है।</p>" },
      img("13-abstract.png", "Abstract of cost", "लागत का Abstract"),
      img("14-export.png", "Export options", "Export के विकल्प"),
    ] },
    { id: "library", t: { en: "9. Rate library: view analysis and change rates", hi: "9. रेट लाइब्रेरी: एनालिसिस देखना और रेट बदलना" }, b: [
      { en: "<p>The <b>Rate library</b> tab lists CPWD DSOR 2023 (with DAR 2023 analysis), CPWD DSR 2021, MPPWD Road SOR 2017, DSR Horticulture 2018 and your uploaded SORs. Click an item to see its <b>SOR rate</b>, <b>updated rate</b> and the full <b>rate analysis</b> (material, labour, machinery, add-ons).</p><ul><li><b>Updated rate comes from:</b> rate analysis, SOR rate, or an entered rate (with a reason).</li><li>Any user can change quantities or rates in the analysis lines — for their own estimates by default, or for everyone (editors, shared library).</li><li><i>Changed only</i> lists items whose rates were changed.</li><li>For one estimate only, type a rate in the item's <i>Updated rate for this estimate only</i> box instead.</li></ul>",
        hi: "<p><b>Rate library</b> टैब में CPWD DSR 2021, MPPWD Road SOR 2017, DSR Horticulture 2018 और आपकी अपलोड की हुई SOR हैं। किसी आइटम पर क्लिक करें — उसका <b>SOR रेट</b>, <b>updated रेट</b> और पूरा <b>rate analysis</b> (material, labour, machinery, add-ons) दिखेगा।</p><ul><li><b>Updated rate comes from:</b> rate analysis, SOR रेट, या खुद डाला रेट (कारण के साथ)।</li><li>कोई भी user analysis की lines में quantity या रेट बदल सकता है — default में केवल अपने एस्टीमेट के लिए, या editor सबके लिए (shared library)।</li><li><i>Changed only</i> से केवल बदले गए आइटम दिखते हैं।</li><li>केवल एक एस्टीमेट के लिए रेट बदलना हो तो आइटम के <i>Updated rate for this estimate only</i> box में लिखें।</li></ul>" },
      img("16-library.png", "CPWD item with its rate analysis", "CPWD आइटम और उसका rate analysis"),
      img("17-library-mp.png", "MPPWD item with MoRTH SDB analysis", "MPPWD आइटम और MoRTH SDB analysis"),
    ] },
    { id: "basic", t: { en: "10. Basic rates (labour, material, machinery)", hi: "10. बेसिक रेट (मज़दूरी, सामग्री, मशीनरी)" }, b: [
      { en: "<p>The <b>Basic rates</b> tab lists all labour, material and machinery rates used by the analyses — switch between CPWD and MPPWD. Every user can type a new rate (for example the current labour rate or cement rate); <b>every item that uses it is recalculated at once</b>. <i>Reset</i> returns to the book rate.</p><p><b>Rate changes apply to:</b> <i>Only my estimates</i> (default) keeps your labour, material, machinery and analysis rates private — other users are not affected and your rates win over the shared library. Editors can switch to <i>Everyone (shared library)</i>. <i>Reset all my rates</i> removes all your personal changes.</p>",
        hi: "<p><b>Basic rates</b> टैब में analysis में लगने वाले सभी labour, material और machinery के रेट हैं — CPWD और MPPWD में बदलें। हर user नया रेट लिख सकता है (जैसे आज की मज़दूरी या सीमेंट का रेट); <b>उसे उपयोग करने वाले सभी आइटम तुरंत दोबारा calculate हो जाते हैं</b>। <i>Reset</i> से किताब वाला रेट वापस आता है।</p><p><b>Rate changes apply to:</b> <i>Only my estimates</i> (default) — आपके labour, material, machinery और analysis रेट केवल आपके एस्टीमेट पर लगते हैं, दूसरे users पर असर नहीं होता। Editor <i>Everyone (shared library)</i> चुनकर सबके लिए बदल सकते हैं। <i>Reset all my rates</i> से आपके सभी निजी बदलाव हट जाते हैं।</p>" },
      img("18-basic-rates.png", "Basic rates — change once, all items follow", "बेसिक रेट — एक बार बदलें, सब आइटम बदल जाते हैं"),
    ] },
    { id: "sor", t: { en: "11. Upload your own SOR", hi: "11. अपनी SOR अपलोड करना" }, b: [
      { en: "<p>In <b>My SORs</b>, choose a <b>PDF, Excel (.xlsx/.xls) or CSV</b> file of any schedule of rates (state PWD, department, market list).</p><ol><li>For Excel/CSV, pick the sheet and tell the app which columns are <b>code, description, unit, rate</b> (and optionally chapter / analysis rate).</li><li>For PDF, the app reads the text and finds items automatically (scanned image PDFs cannot be read).</li><li>Check the preview, give the SOR a name and short name, and click <b>Save</b>.</li></ol><p>The SOR becomes a rate book that <b>only you</b> can see; search it from any estimate. Your saved <b>NS items</b> are also listed here.</p>",
        hi: "<p><b>My SORs</b> में किसी भी schedule of rates (राज्य PWD, विभाग, मार्केट लिस्ट) की <b>PDF, Excel (.xlsx/.xls) या CSV</b> फ़ाइल चुनें।</p><ol><li>Excel/CSV में sheet चुनें और बताएं कि कौन-सा column <b>code, description, unit, rate</b> है (chapter / analysis rate वैकल्पिक)।</li><li>PDF में ऐप text पढ़कर आइटम अपने-आप ढूँढता है (स्कैन की हुई image वाली PDF नहीं पढ़ी जा सकती)।</li><li>Preview जाँचें, SOR का नाम और छोटा नाम दें, और <b>Save</b> दबाएँ।</li></ol><p>यह SOR एक rate book बन जाती है जिसे <b>केवल आप</b> देख सकते हैं; किसी भी एस्टीमेट में खोजें। आपके सेव किए <b>NS आइटम</b> भी यहीं दिखते हैं।</p>" },
      img("19-sor-upload.png", "Uploading an SOR: column mapping and preview", "SOR अपलोड: column चुनना और preview"),
    ] },
    { id: "admin", t: { en: "12. Super admin: users and activation", hi: "12. सुपर एडमिन: यूज़र और एक्टिवेशन" }, b: [
      { en: "<p>Only the super admin sees the <b>Users</b> tab:</p><ul><li><b>+ Create user:</b> name, email, password, role and licence (trial, until a date, lifetime). The account works immediately.</li><li><b>Role:</b> User, or Editor (can change library and basic rates).</li><li><b>Licence:</b> activate for 1/3/6 months, 1 year, lifetime, <b>set an expiry date</b>, extend trial or deactivate.</li><li><b>Password:</b> set a new password (signs the user out) or email a reset link.</li><li><b>Open projects:</b> view any user's estimates; <b>Projects of</b> dropdown switches users.</li></ul>",
        hi: "<p><b>Users</b> टैब केवल सुपर एडमिन को दिखता है:</p><ul><li><b>+ Create user:</b> नाम, ईमेल, पासवर्ड, role और licence (trial, किसी तारीख तक, lifetime)। अकाउंट तुरंत चालू हो जाता है।</li><li><b>Role:</b> User, या Editor (library और basic rates बदल सकते हैं)।</li><li><b>Licence:</b> 1/3/6 महीने, 1 साल, lifetime के लिए activate करें, <b>expiry तारीख चुनें</b>, trial बढ़ाएँ या deactivate करें।</li><li><b>Password:</b> नया पासवर्ड सेट करें (user लॉगआउट हो जाता है) या reset लिंक ईमेल करें।</li><li><b>Open projects:</b> किसी भी user के एस्टीमेट देखें; <b>Projects of</b> ड्रॉपडाउन से user बदलें।</li></ul>" },
      img("20-users.png", "Users tab: create user, licence and password", "Users टैब: user बनाना, licence और password"),
      { en: "<ul><li><b>Search &amp; filter:</b> search by name, email or phone; show only <i>Ending in 7 days</i>, <i>Expired</i>, <i>On trial</i>, <i>Blocked</i>, a group … <i>Download users</i> gives an Excel-ready CSV.</li><li><b>Licence reminders:</b> people whose trial / licence ends within 7 days or has ended, with a ready message for WhatsApp (type their mobile number in the Email / phone column) or email, and a Renew list.</li><li><b>Payments:</b> <i>Payments</i> on a row records amount, date, months, receipt no. and note; tick <i>also activate</i> to extend the licence at the same time. The Payments panel shows this month, last month, the financial year and the total.</li><li><b>Block / Sign out:</b> <i>Sign out</i> ends the person's session on their computer; <i>Block</i> stops them from using the app until you click <i>Unblock</i>.</li><li><b>Activity log:</b> sign-ins, new / deleted / sent estimates and Excel exports, for everyone or one person.</li><li><b>Notice to all users:</b> a message shown at the top of the app for everyone until they hide it.</li><li><b>Groups:</b> <i>Make admin</i> makes a member the group admin. A group admin gets a <i>Users</i> tab of their own: add members by email, remove them, open members' projects (read-only), see their activity, and set <i>group rates</i> (Basic rates → Rate changes apply to: My group) that every member's estimates use. Saved analyses can be shared with a group.</li></ul>",
        hi: "<ul><li><b>खोज और फ़िल्टर:</b> नाम, ईमेल या फोन से खोजें; सिर्फ <i>7 दिन में खत्म</i>, <i>Expired</i>, <i>Trial</i>, <i>Blocked</i>, किसी ग्रुप के लोग देखें। <i>Download users</i> से Excel में खुलने वाली CSV मिलती है।</li><li><b>लाइसेंस रिमाइंडर:</b> जिनका trial / licence 7 दिन में खत्म हो रहा है या हो चुका है, उनके लिए WhatsApp (Email / phone कॉलम में मोबाइल नंबर लिखें) या ईमेल का तैयार संदेश और Renew विकल्प।</li><li><b>पेमेंट:</b> पंक्ति में <i>Payments</i> से रकम, तारीख, महीने, रसीद नं. और नोट दर्ज करें; <i>also activate</i> से उसी समय licence बढ़ जाता है। Payments पैनल में इस महीने, पिछले महीने, वित्त वर्ष और कुल रकम दिखती है।</li><li><b>Block / Sign out:</b> <i>Sign out</i> उस व्यक्ति का लॉगिन बंद करता है; <i>Block</i> करने पर वह <i>Unblock</i> तक ऐप नहीं चला सकता।</li><li><b>Activity log:</b> लॉगिन, नया / हटाया / भेजा गया एस्टीमेट और Excel export — सबका या एक व्यक्ति का।</li><li><b>सभी को सूचना:</b> ऐप के ऊपर सबको दिखने वाला संदेश, जब तक वे उसे छिपा न दें।</li><li><b>ग्रुप:</b> <i>Make admin</i> से सदस्य ग्रुप एडमिन बनता है। ग्रुप एडमिन को अपना <i>Users</i> टैब मिलता है: ईमेल से सदस्य जोड़ना/हटाना, सदस्यों के प्रोजेक्ट (सिर्फ देखने के लिए) और activity देखना, और <i>ग्रुप रेट</i> (Basic rates → Rate changes apply to: My group) जो हर सदस्य के एस्टीमेट में लगते हैं। सेव एनालिसिस ग्रुप के साथ साझा हो सकते हैं।</li></ul>" },
    ] },
    { id: "design", t: { en: "13. Design Studio — structural design, drawings, BBS", hi: "13. डिज़ाइन स्टूडियो — स्ट्रक्चरल डिज़ाइन, ड्रॉइंग, BBS" }, b: [
      { en: "<p>Open the <b>Design Studio</b> tab. Pick a structure — <b>Steel</b> (portal-frame shed, roof truss, purlin, steel beam, column + base plate), <b>Drains, culverts &amp; roads</b> (RCC drain, box culvert, hume pipe culvert, cantilever retaining wall, circular water tank, flexible pavement IRC 37), <b>RCC building</b> (beam, slab, column, isolated footing, staircase) or <b>Bridges &amp; frames</b> (solid slab bridge, T-beam bridge, multi-storey RCC frame).</p><ul><li><b>Mode:</b> <i>Design</i> (the app sizes the member), <i>Check my design</i> (you give sizes / steel; the app checks) or <i>Thumb rule</i> (quick sizing, then code check).</li><li><b>Inputs</b> are grouped (geometry, loads, materials…). Change any value — everything is recalculated at once. <i>Save inputs</i> / <i>Load inputs</i> keep a design as a small file.</li><li>The status shows <b>PASS / CHECK / FAIL</b>, the maximum utilisation and the headline results.</li></ul>",
        hi: "<p><b>Design Studio</b> टैब खोलें। स्ट्रक्चर चुनें — <b>स्टील</b> (पोर्टल फ्रेम शेड, रूफ ट्रस, पर्लिन, स्टील बीम, कॉलम + बेस प्लेट), <b>नाली, पुलिया व सड़क</b> (RCC नाली, बॉक्स कल्वर्ट, ह्यूम पाइप कल्वर्ट, रिटेनिंग वॉल, गोल पानी टंकी, फ्लेक्सिबल पेवमेंट IRC 37), <b>RCC भवन</b> (बीम, स्लैब, कॉलम, फुटिंग, सीढ़ी) या <b>पुल व फ्रेम</b> (सॉलिड स्लैब ब्रिज, T-बीम ब्रिज, बहुमंज़िला RCC फ्रेम)।</p><ul><li><b>Mode:</b> <i>Design</i> (ऐप साइज़ निकालेगा), <i>Check my design</i> (आप साइज़/सरिया दें, ऐप जाँचेगा) या <i>Thumb rule</i> (जल्दी साइज़, फिर कोड जाँच)।</li><li><b>Inputs</b> समूहों में हैं (ज्यामिति, लोड, सामग्री…)। कोई भी मान बदलें — सब तुरंत दोबारा calculate होता है। <i>Save / Load inputs</i> से डिज़ाइन फ़ाइल में रखें।</li><li>ऊपर <b>PASS / CHECK / FAIL</b>, अधिकतम utilisation और मुख्य परिणाम दिखते हैं।</li></ul>" },
      img("22-design.png", "Design Studio: module, mode and inputs", "डिज़ाइन स्टूडियो: मॉड्यूल, mode और inputs"),
      { en: "<ul><li><b>Drawings:</b> A3 sheets with title block (your estimate header / saved firm) — download all sheets as <b>PDF</b> or <b>DXF (AutoCAD, 1:1 in mm)</b>, or one sheet as SVG.</li><li><b>Calculation:</b> every step with formula, substituted values, result, unit, IS / IRC clause and PASS / FAIL. Click 🔎 to open it in the <b>Formula checker</b>, change any variable and see the new result.</li><li><b>Missing, checks &amp; fixes:</b> failed checks, warnings and what is still to be designed or verified (Critical / Important / Advisory).</li><li><b>Thumb rules</b>, <b>BBS</b> — every row shows how its cut length was found (out-to-out lengths − bend deductions 45° 1d / 90° 2d / 135° 3d, stirrup hooks max(10d, 75 mm), laps max(Ld, 30φ) for bars longer than 12 m), plus a steel abstract by diameter. The same BBS is on the BBS drawing sheet, in the Excel workbook and the report (CSV download too). <b>Editable:</b> change Nos, cut length or Ø of any row (weight, steel quantity, drawing sheet and reports follow; <i>Undo my BBS edits</i> restores), and change the <i>BBS rules</i> (bend deductions, hooks, stock length, laps, support widths, leg lengths) to your site practice.</li><li><b>Site values</b> (Mining area): SBC factor, soil γ, φ, μ, surcharge, live-load factor, coal dust, k1, concrete grade, exposure and extra cover can be changed to the actual site; changes are listed in the calculation.</li><li><b>New modules:</b> drain / trench cover slab (IRC loads or mine dumpers), septic tank + soak pit (IS 2470), boundary wall with RCC pillars, combined footing.</li><li><b>Quantities → Estimate:</b> adds the quantities with all measurement rows to the open estimate (new part or an existing one). Matching CPWD (DSOR 2023 / DSR 2021) and MPPWD items are used automatically; others come in as Non-SOR at an indicative rate.</li><li><b>Reports:</b> calculation workbook (.xlsx with live formulas and ✔/✘ match column) and a full HTML report to print as PDF. Enter <i>Designed / Checked / Approved by</i> for the title block.</li></ul><p class='muted'>The Design Studio is a design aid — the results must be checked and signed by a qualified structural engineer.</p>",
        hi: "<ul><li><b>Drawings:</b> टाइटल ब्लॉक (आपके एस्टीमेट का header / saved firm) के साथ A3 शीट — सभी शीट <b>PDF</b> या <b>DXF (AutoCAD, mm में 1:1)</b> में, या एक शीट SVG में डाउनलोड करें।</li><li><b>Calculation:</b> हर स्टेप — formula, मान डालकर, परिणाम, unit, IS / IRC clause और PASS / FAIL। 🔎 दबाकर <b>Formula checker</b> में कोई भी variable बदलें और नया परिणाम देखें।</li><li><b>Missing &amp; checks:</b> fail हुई जाँच, चेतावनी और क्या अभी डिज़ाइन/जाँच बाकी है (Critical / Important / Advisory)।</li><li><b>Thumb rules</b>, <b>BBS</b> (CSV डाउनलोड)।</li><li><b>Quantities → Estimate:</b> सभी नाप की rows के साथ मात्राएँ खुले एस्टीमेट में जोड़ता है (नया Part या पुराना)। मिलते-जुलते CPWD (DSOR 2023 / DSR 2021) और MPPWD आइटम अपने-आप लगते हैं; बाकी Non-SOR (अनुमानित रेट) बनते हैं।</li><li><b>Reports:</b> calculation workbook (.xlsx, चालू formulas और ✔/✘ कॉलम) और पूरी HTML रिपोर्ट (PDF में प्रिंट करें)। टाइटल ब्लॉक के लिए <i>Designed / Checked / Approved by</i> भरें।</li></ul><p class='muted'>डिज़ाइन स्टूडियो एक सहायक उपकरण है — परिणाम किसी योग्य स्ट्रक्चरल इंजीनियर से जँचवाकर हस्ताक्षर कराएँ।</p>" },
      img("23-design-calc.png", "Calculation with formulas, clauses and checks", "Formula, clause और जाँच के साथ calculation"),
      { en: "<h3>Mining-area sites, diagnosis and load guide</h3><ul><li><b>Site: General / ⛏️ Mining area (SECL)</b> — for Korba / Gevra / Dipka / Kusmunda and nearby sites choose <i>Mining area</i>. In design mode the app then uses exposure Severe, M30, 45–50 mm cover; in both modes SBC × 0.8, soil γ 20, φ ≤ 28°, base friction ≤ 0.45, surcharge ≥ 24 kN/m², imposed load × 1.10, coal dust on roofs and wind k1 1.07. Your inputs stay as typed; a yellow strip shows each value the design used, and the calculation gets a <i>Site condition – mining area</i> section (DGMS blast vibration, underground workings, sulphate test, paint system).</li><li><b>Bar detailing: Good practice / IS code minimum</b> — practice sizes (slab ≥ 10Ø main, footing / ground-contact ≥ 12Ø, column ties ≥ 8Ø, beam hangers ≥ 12Ø) or the bare IS 456 minimum. Each bar choice is explained in the calculation.</li><li><b>Hints under inputs</b> show the usual value (general or mine) with a <i>Use</i> button; a red / orange note means the value is at a limit or on the unsafe side.</li><li><b>🩺 Missing, checks &amp; fixes</b> runs a diagnosis: every failed / warning / &gt; 90 % check is listed with the inputs that fix it and the value needed (e.g. <i>Base width 2.6 → 2.86 m – check passes</i>). <i>Apply</i> sets the value. 🛠️ design choices come first, 📏 geometry next, 📋 load / site data last (change those only if the real condition is different). The sensitivity table shows what happens when each input is taken 10 % lower or higher.</li><li><b>Load guide</b> tab: unit weights, imposed loads, dumpers and HEMM, CHP, transformers, railway (25 t / DFC), IRC vehicles, surcharge, wind and seismic for Chhattisgarh, the mining-area factors of safety, DGMS blast-vibration limits and a checklist — and the recommended values for the open module with <i>Use</i> buttons.</li><li><b>Complete steel shed – footing to roof</b>: portal (rolled / PEB tapered), Pratt / Howe / Fink truss or mono-slope; purlins, girts, bracing, gable, crane, every bolt group, base plate, anchor bolts, pedestal and footing with BOM, BBS and drawings.</li><li><b>Culverts</b> (box / pipe): first choose the <b>location</b> — <i>Road</i> (IRC Class A / AA / 70R), <i>Railway</i> (IRS 25 t / DFC 32.5 t, railway rules only – the mining-area profile is not mixed in, ballast and track inputs appear only here) or <i>Mine haul road</i> (dumpers 35–240 t, mine environment). Fill dispersion and crack-width checks for each. <b>Retaining wall</b>: choose weep holes + filter media (count, Ø and spacing checked) or no weep holes (water pressure and uplift added).</li><li><b>Add to estimate</b>: choose the <i>open estimate</i> (new or existing part), <i>another of your estimates</i>, or a <i>new estimate</i>.</li></ul>",
        hi: "<h3>खदान क्षेत्र, diagnosis और load guide</h3><ul><li><b>Site: General / ⛏️ Mining area (SECL)</b> — कोरबा / गेवरा / दीपका / कुसमुंडा व आसपास के लिए <i>Mining area</i> चुनें। Design mode में exposure Severe, M30, 45–50 mm cover; दोनों mode में SBC × 0.8, मिट्टी γ 20, φ ≤ 28°, घर्षण ≤ 0.45, surcharge ≥ 24 kN/m², live load × 1.10, छत पर कोयला धूल, हवा k1 1.07। आपके inputs वैसे ही रहते हैं; पीली पट्टी में दिखता है कि डिज़ाइन ने कौन सा मान लिया। Calculation में <i>Site condition – mining area</i> खंड (DGMS ब्लास्ट कंपन, भूमिगत खदान, सल्फेट जाँच, पेंट सिस्टम)।</li><li><b>Bar detailing: Good practice / IS code minimum</b> — practice साइज़ (स्लैब ≥ 10Ø, फुटिंग ≥ 12Ø, कॉलम टाई ≥ 8Ø) या IS 456 न्यूनतम।</li><li>हर input के नीचे सामान्य मान और <i>Use</i> बटन; लाल / नारंगी नोट = सीमा पर या असुरक्षित तरफ़।</li><li><b>🩺 Missing, checks &amp; fixes</b>: हर fail / warning / &gt; 90 % check के लिए कौन सा input कितना बदलें (जैसे <i>Base width 2.6 → 2.86 m – check pass</i>) — <i>Apply</i> से सेट करें। 🛠️ डिज़ाइन विकल्प पहले, 📏 ज्यामिति, 📋 लोड / साइट डेटा अंत में (तभी बदलें जब असली स्थिति वैसी हो)। Sensitivity तालिका: हर input 10 % कम / ज़्यादा करने पर असर।</li><li><b>Load guide</b> टैब: इकाई भार, live load, डम्पर व HEMM, CHP, ट्रांसफ़ॉर्मर, रेलवे, IRC वाहन, surcharge, हवा व भूकंप, खदान FoS, DGMS कंपन सीमा व checklist — खुले module के लिए <i>Use</i> बटन।</li><li><b>Complete steel shed – footing to roof</b>: पोर्टल / PEB / ट्रस / मोनो-स्लोप; पर्लिन, गर्ट, ब्रेसिंग, क्रेन, हर बोल्ट, बेस प्लेट, एंकर बोल्ट, पेडेस्टल व फुटिंग, BOM, BBS व ड्रॉइंग।</li><li><b>BBS / साइट मान</b>: BBS की हर पंक्ति (नग, कट लंबाई, Ø) और BBS नियम, तथा खदान साइट के मान (SBC गुणक, surcharge आदि) बदले जा सकते हैं।</li><li><b>Culvert</b>: पहले <b>location</b> चुनें — <i>Road</i> (IRC A / AA / 70R), <i>Railway</i> (25 t / DFC, सिर्फ़ रेलवे नियम, खदान प्रोफ़ाइल नहीं मिलता; ballast / track inputs सिर्फ़ यहीं) या <i>Mine haul road</i> (डम्पर 35–240 t)। <b>Retaining wall</b>: weep holes + filter (संख्या, Ø, दूरी जाँच) या बिना weep hole (पानी का दबाव व uplift)।</li><li><b>Estimate में जोड़ें</b>: खुला एस्टीमेट (नया / मौजूदा part), आपका कोई दूसरा एस्टीमेट, या नया एस्टीमेट।</li></ul>" },
      img("25-diagnosis.png", "Diagnosis: what fails and which input to change", "Diagnosis: क्या fail है और कौन सा input बदलें"),
      img("26-loadguide.png", "Load guide for general and mining sites", "सामान्य व खदान साइट के लिए load guide"),
    ] },
    { id: "review", t: { en: "14. Drawing review and codes", hi: "14. ड्रॉइंग रिव्यू और कोड" }, b: [
      { en: "<p>In Design Studio → <b>Drawing review</b>, upload a <b>DXF</b> (read completely: text, layers, dimensions, bar call-outs) or <b>PDF</b> (text extracted where possible). Choose the drawing type; the app lists findings with severity and suggestions and gives a score. Tick <i>Compare with current design</i> to compare call-outs with the design you just ran. Images (photos / scans) need the optional <b>AI review</b> with your own Anthropic API key — the key is used for that request only.</p><p><b>Codes &amp; thumb rules</b> lists every IS / IRC code and book used, and quick thumb rules for site checks.</p>",
        hi: "<p>Design Studio → <b>Drawing review</b> में <b>DXF</b> (पूरी पढ़ी जाती है: text, layers, dimensions, सरिया call-outs) या <b>PDF</b> (जहाँ संभव हो text) अपलोड करें। ड्रॉइंग का प्रकार चुनें; ऐप गंभीरता और सुझाव के साथ कमियाँ और score देता है। <i>Compare with current design</i> से अभी के डिज़ाइन से मिलान करें। फोटो/स्कैन के लिए अपनी Anthropic API key से <b>AI review</b> (key सिर्फ़ उसी बार इस्तेमाल होती है)।</p><p><b>Codes &amp; thumb rules</b> में सभी IS / IRC कोड, किताबें और साइट के thumb rules हैं।</p>" },
      img("24-review.png", "Drawing review of an uploaded DXF", "अपलोड की गई DXF का रिव्यू"),
    ] },
    { id: "modules", t: { en: "15. Design modules and the inputs that matter", hi: "15. डिज़ाइन मॉड्यूल और मुख्य inputs" }, b: [
      { en: "<p>The inputs below are the ones that change the result of each module. Choosing ⛏️ <b>Mining area</b> applies safer SBC, soil, surcharge, exposure and cover values automatically (editable under Site values). Inputs not listed mostly affect drawings and quantities only.</p><h3>Steel structures / स्टील</h3><div class='tw'><table class='t'><thead><tr><th>Module</th><th>Major inputs (change the result)</th><th>What it designs / checks</th></tr></thead><tbody><tr><td><b>Complete steel shed – footing to roof</b></td><td>span, bay & number of bays, eave height, roof slope, style (portal / PEB / truss / mono), wind (city / Vb, terrain, k1–k4, wall openings), cladding & dust load, crane capacity, steel grade, SBC</td><td>frames, purlins, girts, bracing, gable, crane girder, every bolt group, base plate & anchor bolts, pedestal, footing, tie beams; BOM, BBS, 14 drawing sheets</td></tr><tr><td><b>Portal frame shed</b></td><td>span, eave, bay, slope, wind (Vb, terrain, k1), sheeting / services load, base pinned or fixed, SBC</td><td>rafter & column sections, purlins, base plate, footing (with moment, thrust, sliding, overturning)</td></tr><tr><td><b>Roof truss shed</b></td><td>span, rise, panels, bay, wind, sheet load, bottom-chord tie spacing</td><td>member forces, angle sizes (shear lag), chord ties, deflection</td></tr><tr><td><b>Purlin</b></td><td>span (bay), spacing, slope, sag rods, wind uplift (Cpe, Cpi, Ka)</td><td>section, biaxial bending, LTB under uplift, deflection</td></tr><tr><td><b>Steel beam / Steel column</b></td><td>span / height, loads, restraint (LLT), effective length factors, axial load & moments</td><td>section, LTB, buckling, interaction, base plate</td></tr></tbody></table></div><h3>Drains, culverts & roads / नाली, पुलिया, सड़क</h3><div class='tw'><table class='t'><thead><tr><th>Module</th><th>Major inputs (change the result)</th><th>What it designs / checks</th></tr></thead><tbody><tr><td><b>RCC open drain</b></td><td>width, depth, soil γ / φ, surcharge, water-tight or not, cover</td><td>wall & base thickness and bars (IS 3370 min steel)</td></tr><tr><td><b>Box culvert</b></td><td>clear span × height, fill, location (Road IRC / Railway IRS / Mine haul road), live load or dumper class, lanes, SBC, ground water, crack limit</td><td>slab & wall thickness and bars, crack width, bearing, sliding, flotation, wing walls</td></tr><tr><td><b>Hume pipe culvert</b></td><td>catchment, rainfall intensity, slope, fill, location & live load, bedding</td><td>pipe size & rows, part-full velocity, pipe class (NP3 / NP4), bedding</td></tr><tr><td><b>Culvert headwall / wing walls</b></td><td>opening size, fill height, layout (splayed / return / straight), RCC / PCC / masonry, location surcharge, soil, SBC</td><td>stability at each section, stem bars, curtain wall & apron</td></tr><tr><td><b>Cantilever retaining wall</b></td><td>height, backfill slope, surcharge, soil γ / φ / μ, SBC, drainage (weep holes or not)</td><td>base width, toe / heel, stem bars, overturning ≥ 2.0, sliding, edge pressures, weep holes</td></tr><tr><td><b>Drain-cum-retaining wall</b></td><td>drain width & depth, retained height on the high side, low-side wall, discharge (or catchment), bed slope, surcharge (road / haul road dumper / footpath), soil, SBC, ground water, weep holes</td><td>Manning capacity & velocity, whole-section overturning / sliding / edge pressures / flotation, both walls & base slab with crack width, BBS, joints with water-stops</td></tr><tr><td><b>Gravity / breast / toe / gabion wall</b></td><td>height, top width, batters / steps, wall type, soil, surcharge, water, seismic</td><td>base width, joint stresses, overturning, sliding, bearing, gabion layers</td></tr><tr><td><b>Circular water tank / Underground sump</b></td><td>capacity, depth, base type, cover; sump: ground water, surcharge, roof</td><td>hoop / plate moments, crack width 0.2 mm, laps 2Ld, flotation (sump)</td></tr><tr><td><b>Drain / cable-trench cover slab</b></td><td>clear span, unit width, wheel load (IRC A / 70R / mine dumper), precast or in-situ</td><td>slab thickness & bars, punching, crack width, lifting hooks</td></tr><tr><td><b>Septic tank & soak pit</b></td><td>users, desludging interval, percolation rate, ground water, brick or RCC</td><td>tank size & compartments, soak pit / trench, wall design (RCC)</td></tr><tr><td><b>Flexible pavement (IRC 37) / Rigid pavement (IRC 58)</b></td><td>traffic (CVPD, growth, VDF, lanes) or dumper class, CBR / k-value, design life, concrete strength</td><td>layer / PQC thickness, fatigue, dowel & tie bars, joints</td></tr></tbody></table></div><h3>RCC building / आरसीसी भवन</h3><div class='tw'><table class='t'><thead><tr><th>Module</th><th>Major inputs (change the result)</th><th>What it designs / checks</th></tr></thead><tbody><tr><td><b>Beam / Slab / Staircase</b></td><td>span, support type, dead & live load, b, grade, exposure & cover</td><td>depth, bars, shear stirrups, deflection, BBS</td></tr><tr><td><b>Column / Isolated footing / Combined footing</b></td><td>axial load & moments, effective length, column size, SBC, property line</td><td>bars & ties, slenderness, footing size, punching & one-way shear, anchorage</td></tr><tr><td><b>Lintel, chajja & plinth beam</b></td><td>opening span, wall thickness & masonry above, chajja projection, plinth span & wall load</td><td>section & bars, torsion (chajja), BBS</td></tr><tr><td><b>Boundary wall</b></td><td>height, pillar spacing, wall thickness, wind (Vb, terrain), SBC, earth / bund against wall</td><td>panel check, pillar bars, plinth beam, pillar footing</td></tr></tbody></table></div><h3>Bridges & frames / पुल व फ्रेम</h3><div class='tw'><table class='t'><thead><tr><th>Module</th><th>Major inputs (change the result)</th><th>What it designs / checks</th></tr></thead><tbody><tr><td><b>Slab bridge / T-beam bridge</b></td><td>span, carriageway width, IRC loading, surfacing, cover, grade</td><td>deck / girder sections and bars, crack width, shear</td></tr><tr><td><b>Multi-storey RCC frame</b></td><td>bays, storeys, heights, loads, seismic zone, soil, importance, SMRF</td><td>beam & column bars, drift, IS 13920 detailing, slenderness</td></tr></tbody></table></div>",
        hi: "<p>नीचे हर मॉड्यूल के वे मुख्य inputs हैं जिनसे गणना का परिणाम बदलता है। ⛏️ <b>Mining area</b> चुनने पर SBC, मिट्टी, surcharge, exposure, cover आदि सुरक्षित मान अपने आप लगते हैं (Site values में बदल सकते हैं)।</p><h3>Steel structures / स्टील</h3><div class='tw'><table class='t'><thead><tr><th>मॉड्यूल</th><th>मुख्य inputs (परिणाम बदलते हैं)</th><th>क्या डिज़ाइन / जाँच होता है</th></tr></thead><tbody><tr><td><b>Complete steel shed – footing to roof</b></td><td>span, bay & number of bays, eave height, roof slope, style (portal / PEB / truss / mono), wind (city / Vb, terrain, k1–k4, wall openings), cladding & dust load, crane capacity, steel grade, SBC</td><td>frames, purlins, girts, bracing, gable, crane girder, every bolt group, base plate & anchor bolts, pedestal, footing, tie beams; BOM, BBS, 14 drawing sheets</td></tr><tr><td><b>Portal frame shed</b></td><td>span, eave, bay, slope, wind (Vb, terrain, k1), sheeting / services load, base pinned or fixed, SBC</td><td>rafter & column sections, purlins, base plate, footing (with moment, thrust, sliding, overturning)</td></tr><tr><td><b>Roof truss shed</b></td><td>span, rise, panels, bay, wind, sheet load, bottom-chord tie spacing</td><td>member forces, angle sizes (shear lag), chord ties, deflection</td></tr><tr><td><b>Purlin</b></td><td>span (bay), spacing, slope, sag rods, wind uplift (Cpe, Cpi, Ka)</td><td>section, biaxial bending, LTB under uplift, deflection</td></tr><tr><td><b>Steel beam / Steel column</b></td><td>span / height, loads, restraint (LLT), effective length factors, axial load & moments</td><td>section, LTB, buckling, interaction, base plate</td></tr></tbody></table></div><h3>Drains, culverts & roads / नाली, पुलिया, सड़क</h3><div class='tw'><table class='t'><thead><tr><th>मॉड्यूल</th><th>मुख्य inputs (परिणाम बदलते हैं)</th><th>क्या डिज़ाइन / जाँच होता है</th></tr></thead><tbody><tr><td><b>RCC open drain</b></td><td>width, depth, soil γ / φ, surcharge, water-tight or not, cover</td><td>wall & base thickness and bars (IS 3370 min steel)</td></tr><tr><td><b>Box culvert</b></td><td>clear span × height, fill, location (Road IRC / Railway IRS / Mine haul road), live load or dumper class, lanes, SBC, ground water, crack limit</td><td>slab & wall thickness and bars, crack width, bearing, sliding, flotation, wing walls</td></tr><tr><td><b>Hume pipe culvert</b></td><td>catchment, rainfall intensity, slope, fill, location & live load, bedding</td><td>pipe size & rows, part-full velocity, pipe class (NP3 / NP4), bedding</td></tr><tr><td><b>Culvert headwall / wing walls</b></td><td>opening size, fill height, layout (splayed / return / straight), RCC / PCC / masonry, location surcharge, soil, SBC</td><td>stability at each section, stem bars, curtain wall & apron</td></tr><tr><td><b>Cantilever retaining wall</b></td><td>height, backfill slope, surcharge, soil γ / φ / μ, SBC, drainage (weep holes or not)</td><td>base width, toe / heel, stem bars, overturning ≥ 2.0, sliding, edge pressures, weep holes</td></tr><tr><td><b>Drain-cum-retaining wall</b></td><td>drain width & depth, retained height on the high side, low-side wall, discharge (or catchment), bed slope, surcharge (road / haul road dumper / footpath), soil, SBC, ground water, weep holes</td><td>Manning capacity & velocity, whole-section overturning / sliding / edge pressures / flotation, both walls & base slab with crack width, BBS, joints with water-stops</td></tr><tr><td><b>Gravity / breast / toe / gabion wall</b></td><td>height, top width, batters / steps, wall type, soil, surcharge, water, seismic</td><td>base width, joint stresses, overturning, sliding, bearing, gabion layers</td></tr><tr><td><b>Circular water tank / Underground sump</b></td><td>capacity, depth, base type, cover; sump: ground water, surcharge, roof</td><td>hoop / plate moments, crack width 0.2 mm, laps 2Ld, flotation (sump)</td></tr><tr><td><b>Drain / cable-trench cover slab</b></td><td>clear span, unit width, wheel load (IRC A / 70R / mine dumper), precast or in-situ</td><td>slab thickness & bars, punching, crack width, lifting hooks</td></tr><tr><td><b>Septic tank & soak pit</b></td><td>users, desludging interval, percolation rate, ground water, brick or RCC</td><td>tank size & compartments, soak pit / trench, wall design (RCC)</td></tr><tr><td><b>Flexible pavement (IRC 37) / Rigid pavement (IRC 58)</b></td><td>traffic (CVPD, growth, VDF, lanes) or dumper class, CBR / k-value, design life, concrete strength</td><td>layer / PQC thickness, fatigue, dowel & tie bars, joints</td></tr></tbody></table></div><h3>RCC building / आरसीसी भवन</h3><div class='tw'><table class='t'><thead><tr><th>मॉड्यूल</th><th>मुख्य inputs (परिणाम बदलते हैं)</th><th>क्या डिज़ाइन / जाँच होता है</th></tr></thead><tbody><tr><td><b>Beam / Slab / Staircase</b></td><td>span, support type, dead & live load, b, grade, exposure & cover</td><td>depth, bars, shear stirrups, deflection, BBS</td></tr><tr><td><b>Column / Isolated footing / Combined footing</b></td><td>axial load & moments, effective length, column size, SBC, property line</td><td>bars & ties, slenderness, footing size, punching & one-way shear, anchorage</td></tr><tr><td><b>Lintel, chajja & plinth beam</b></td><td>opening span, wall thickness & masonry above, chajja projection, plinth span & wall load</td><td>section & bars, torsion (chajja), BBS</td></tr><tr><td><b>Boundary wall</b></td><td>height, pillar spacing, wall thickness, wind (Vb, terrain), SBC, earth / bund against wall</td><td>panel check, pillar bars, plinth beam, pillar footing</td></tr></tbody></table></div><h3>Bridges & frames / पुल व फ्रेम</h3><div class='tw'><table class='t'><thead><tr><th>मॉड्यूल</th><th>मुख्य inputs (परिणाम बदलते हैं)</th><th>क्या डिज़ाइन / जाँच होता है</th></tr></thead><tbody><tr><td><b>Slab bridge / T-beam bridge</b></td><td>span, carriageway width, IRC loading, surfacing, cover, grade</td><td>deck / girder sections and bars, crack width, shear</td></tr><tr><td><b>Multi-storey RCC frame</b></td><td>bays, storeys, heights, loads, seismic zone, soil, importance, SMRF</td><td>beam & column bars, drift, IS 13920 detailing, slenderness</td></tr></tbody></table></div>" },
      img("27-mine-site.png", "Mining area: safer values applied and editable site values", "खदान क्षेत्र: सुरक्षित मान और बदलने योग्य साइट मान"),
      img("28-bbs-edit.png", "Editable BBS with the cut-length formula of every bar", "हर सरिये के कट-लंबाई सूत्र के साथ बदलने योग्य BBS"),
      img("29-new-module.png", "New module example: drain cover slab for dumper loading", "नया मॉड्यूल: डम्पर लोड के लिए नाली कवर स्लैब"),
      { en: "<ul><li><b>New: Masonry, water &amp; site works</b> – <i>Brick masonry water tank / sump</i> (RCC base, RCC horizontal bands, roof slab; IS 1905 + IS 3370), <i>Inspection chamber / manhole</i> (size by depth, CI cover by traffic, number on the run), <i>Rain-water recharge pit / trench / bore</i> (CGWB), <i>Masonry lined / garland drain</i> (Manning, velocity, wall check), <i>Oil &amp; grease trap</i> for wash bays / workshops, <i>Chain-link / barbed-wire fencing</i>. Under Steel structures: <i>Wind / dust barrier</i> for coal yards, CHP and sidings (posts, girts, sheet or wind-net, footings).</li><li><b>Free / custom mode:</b> when the size is fixed by the site, choose <i>Free / custom (my dimensions)</i>. Enter your dimensions; the app keeps them, sizes the bars / sections so that steel and strength checks pass, and shows every other check (seismic, serviceability, code limits) only as an orange suggestion – the drawing, BBS and quantities are always produced.</li></ul>",
        hi: "<ul><li><b>नया: ईंट चिनाई, पानी व साइट कार्य</b> – <i>ईंट की पानी टंकी / संप</i> (RCC बेस, RCC बैंड, छत स्लैब; IS 1905 + IS 3370), <i>इंस्पेक्शन चैंबर / मैनहोल</i> (गहराई अनुसार साइज, ट्रैफिक अनुसार CI कवर, लाइन पर संख्या), <i>वर्षा जल रिचार्ज पिट / ट्रेंच / बोर</i> (CGWB), <i>चिनाई / गारलैंड नाली</i> (मैनिंग, वेग, दीवार जाँच), <i>वॉश बे / वर्कशॉप के लिए ऑयल व ग्रीस ट्रैप</i>, <i>चेन-लिंक / कांटेदार तार फेंसिंग</i>। स्टील स्ट्रक्चर में: कोल यार्ड, CHP, साइडिंग के लिए <i>विंड / डस्ट बैरियर</i> (पोस्ट, गर्ट, शीट या विंड-नेट, फुटिंग)।</li><li><b>Free / custom मोड:</b> जब साइज साइट से तय हो, <i>Free / custom (my dimensions)</i> चुनें। अपनी डाइमेंशन डालें; ऐप उन्हें वैसे ही रखता है, सरिया / सेक्शन इतना करता है कि स्टील व स्ट्रेंथ जाँच पास हो, और बाकी जाँच (सीस्मिक, सर्विसेबिलिटी, कोड लिमिट) केवल नारंगी सुझाव के रूप में दिखाता है – ड्रॉइंग, BBS और मात्राएँ हमेशा बनती हैं।</li></ul>" },
    ] },
    { id: "firms", t: { en: "16. Saved firms, market items and departments", hi: "16. सेव फर्म, मार्केट आइटम और विभाग" }, b: [
      { en: "<ul><li><b>Saved firms / letter-heads:</b> in <i>Header, parts &amp; GST</i>, fill the header and signatures, then <i>Save current header as firm</i>. Pick a firm when creating a new estimate, or <i>Apply</i> it to the open one. The header prints on every Excel sheet and drawing title block.</li><li><b>Market items 2026:</b> in <i>Suggested items</i>, the group <i>Market items 2026 (Non-SOR)</i> has WPC / PVC louver panels with or without LED profile, ceilings &amp; cove lighting, complete toilets, demolition, doors &amp; glazing, flooring, kitchens, coatings, waterproofing, outdoor &amp; play, roofing &amp; canopies, partitions &amp; façade and mines safety — with indicative rates (≈) to replace by quotations.</li><li><b>Departments:</b> choose Civil, E&amp;M (beta), PHE or Horticulture in the top bar; the suggested-item groups follow the department.</li></ul>",
        hi: "<ul><li><b>सेव फर्म / लेटर-हेड:</b> <i>Header, parts &amp; GST</i> में header और signatures भरें, फिर <i>Save current header as firm</i>। नया एस्टीमेट बनाते समय फर्म चुनें, या खुले एस्टीमेट पर <i>Apply</i> करें। Header हर Excel शीट और ड्रॉइंग टाइटल ब्लॉक पर छपता है।</li><li><b>मार्केट आइटम 2026:</b> <i>Suggested items</i> में <i>Market items 2026 (Non-SOR)</i> समूह — LED प्रोफाइल सहित/रहित WPC / PVC लूवर पैनल, सीलिंग व कोव लाइट, पूरा टॉयलेट, तोड़-फोड़, दरवाज़े व काँच, फ़्लोरिंग, किचन, कोटिंग, वॉटरप्रूफ़िंग, आउटडोर व खेल, रूफ़िंग व कैनोपी, पार्टिशन व फ़साड, खदान सुरक्षा — अनुमानित रेट (≈) के साथ, quotation से बदलें।</li><li><b>विभाग:</b> ऊपर की पट्टी में Civil, E&amp;M (beta), PHE या Horticulture चुनें; सुझाए गए आइटम विभाग के अनुसार बदलते हैं।</li></ul>" },
    ] },
    { id: "ancheck", t: { en: "17. Check and edit the analysis before export", hi: "17. एक्सपोर्ट से पहले एनालिसिस जाँचें और बदलें" }, b: [
      { en: "<ul><li><b>Same item numbers:</b> the Excel <i>Analysis</i> sheet now uses the item number of the measurement / abstract (Part A item 3, Part B item 1 …) with the SOR item code, e.g. <i>MPPWD SOR 2025 item No. 5.6 a (i)</i>. The MoRTH / DAR reference is printed only as a note.</li><li><b>Analysis check tab:</b> Estimates → <i>Analysis check</i> lists every item with SOR rate, rate used and a status (OK / adjustment / no analysis / unit mismatch / edited). Open any item to see its analysis line by line.</li><li><b>Edit for this estimate:</b> change a quantity, rate or % in the analysis (also from <i>Items &amp; measurement → Check / edit rate analysis</i>). Only this estimate changes and the Excel prints the same figures. <i>Undo my analysis edits</i> restores the library analysis.</li><li><b>Units:</b> each analysis line has a unit selector (kg ↔ quintal ↔ tonne, litre ↔ KL ↔ cum, sqm ↔ sqft, metre ↔ km, each ↔ 100/1000 nos). Quantity and rate convert together, the amount stays the same. If a rate is per tonne but the quantity is in kg the line is marked and one click converts the rate.</li><li><b>Change the SOR item, keep the measurement:</b> open the item in <i>Items &amp; measurement → Change SOR item (keep measurement)</i> and pick the new item (best matches from DSOR 2023 / MPPWD SOR 2025 are suggested). In <i>Analysis check</i> the button <i>Move them to DSOR 2023 / MPPWD SOR 2025</i> does it for all old items at once. If the unit changes within the same kind (kg → tonne, cum → litre) the quantity is converted and the measurement sheet shows the conversion.</li><li><b>One measurement in 2–3 items:</b> <i>Use this measurement in other items</i> links ticked items (a “same as item …” row, × factor editable) or adds a new item that takes its quantity from this one.</li><li><b>Adjustment line:</b> when the printed SOR rate differs from the standard analysis (binder, lead, local rates) the difference is shown as one line, so the analysis always ends at the rate used in the abstract.</li></ul>",
        hi: "<ul><li><b>एक जैसे आइटम नंबर:</b> Excel की <i>Analysis</i> शीट में अब वही नंबर आता है जो मेज़रमेंट / एब्स्ट्रैक्ट में है (Part A item 3, Part B item 1 …) और साथ में SOR का आइटम कोड, जैसे <i>MPPWD SOR 2025 item No. 5.6 a (i)</i>। MoRTH / DAR का संदर्भ सिर्फ़ नोट में।</li><li><b>Analysis check टैब:</b> Estimates → <i>Analysis check</i> में हर आइटम का SOR रेट, उपयोग हुआ रेट और स्थिति (OK / adjustment / analysis नहीं / unit mismatch / edited) दिखती है। किसी भी आइटम को खोलकर पूरा एनालिसिस देखें।</li><li><b>इस एस्टीमेट के लिए बदलें:</b> एनालिसिस में quantity, rate या % बदलें (<i>Items &amp; measurement → Check / edit rate analysis</i> से भी)। सिर्फ़ यही एस्टीमेट बदलता है और Excel में वही आंकड़े छपते हैं। <i>Undo my analysis edits</i> से लाइब्रेरी वाला एनालिसिस वापस।</li><li><b>यूनिट:</b> हर लाइन में यूनिट चुनें (kg ↔ quintal ↔ tonne, litre ↔ KL ↔ cum, sqm ↔ sqft, metre ↔ km, each ↔ 100/1000 nos)। Quantity और rate साथ में बदलते हैं, amount वही रहता है। रेट tonne का और quantity kg में हो तो लाइन पर चेतावनी आती है और एक क्लिक में रेट बदल जाता है।</li><li><b>मेज़रमेंट वही रखकर SOR आइटम बदलें:</b> <i>Items &amp; measurement → Change SOR item (keep measurement)</i> से नया आइटम चुनें (DSOR 2023 / MPPWD SOR 2025 के मिलते-जुलते आइटम सुझाए जाते हैं)। <i>Analysis check</i> में <i>Move them to DSOR 2023 / MPPWD SOR 2025</i> से सभी पुराने आइटम एक साथ बदल जाते हैं। यूनिट उसी तरह की बदले (kg → tonne, cum → litre) तो मात्रा अपने आप बदलती है और मेज़रमेंट शीट में दिखती है।</li><li><b>एक मेज़रमेंट 2–3 आइटम में:</b> <i>Use this measurement in other items</i> से चुने गए आइटम जोड़ें (“same as item …” पंक्ति, factor बदल सकते हैं) या ऐसा नया आइटम जोड़ें जो इसकी मात्रा ले।</li><li><b>Adjustment लाइन:</b> SOR का छपा रेट मानक एनालिसिस से अलग हो (binder, lead, लोकल रेट) तो फ़र्क एक लाइन में दिखता है, ताकि एनालिसिस का अंतिम रेट एब्स्ट्रैक्ट वाले रेट के बराबर रहे।</li></ul>" },
      { en: "<ul><li><b>Add a line:</b> open <i>Check / edit rate analysis</i> under the item in Items &amp; measurement. In <i>Add a line</i> search a basic rate (mason, cement, JCB, bitumen…) or another SOR item, or click <i>+ Own line (MoRTH / market)</i> and type the description, unit, quantity and rate yourself, e.g. a line read from the MoRTH Data Book. Pick whether it is material, labour, machinery, carriage or a line added after overheads.</li><li><b>Remove a line:</b> click ✕ on the line; it is struck through and left out. <i>Restore</i> brings it back.</li><li><b>Save for future use:</b> after editing, click <i>Save this analysis for future use</i> and give it a name. Next time you add the same SOR item to any estimate, the saved analysis is shown under the item and in the analysis panel; click <i>Use</i> to apply it. Saved analyses are part of your backup.</li><li><b>Sub-analyses:</b> a line that is itself an analysis (concrete of a grade, mortar, a MoRTH sub-item …) has <i>Show analysis</i>. In the Excel <i>Analysis</i> sheet every such sub-analysis is printed once, at the end, numbered S-1, S-2 …, and the line says which one to see.</li><li><b>Large difference from the SOR (MPPWD 2025):</b> where the MoRTH analysis with the same description differs a lot from the SOR rate, the item shows <i>Check analysis</i> while you search, a warning when you add it, and the adjustment line is highlighted. After checking you can tick <i>Use the analysis rate without this adjustment</i>.</li></ul>",
        hi: "<ul><li><b>लाइन जोड़ना:</b> Items &amp; measurement में आइटम के नीचे <i>Check / edit rate analysis</i> खोलें। <i>Add a line</i> में बेसिक रेट (mason, cement, JCB, bitumen…) या कोई दूसरा SOR आइटम खोजें, या <i>+ Own line (MoRTH / market)</i> दबाकर विवरण, यूनिट, मात्रा और रेट खुद लिखें — जैसे MoRTH Data Book से देखी गई लाइन। चुनें कि यह material, labour, machinery, carriage है या overhead के बाद जुड़ने वाली लाइन।</li><li><b>लाइन हटाना:</b> लाइन पर ✕ दबाएँ; वह कटी हुई दिखेगी और जोड़ में नहीं आएगी। <i>Restore</i> से वापस आ जाती है।</li><li><b>आगे के लिए सेव:</b> बदलाव के बाद <i>Save this analysis for future use</i> दबाएँ और नाम दें। अगली बार किसी भी एस्टीमेट में वही SOR आइटम जोड़ने पर सेव किया एनालिसिस आइटम के नीचे दिखेगा; <i>Use</i> दबाकर लगाएँ। सेव एनालिसिस बैकअप में भी आते हैं।</li><li><b>सब-एनालिसिस:</b> जो लाइन खुद एक एनालिसिस है (किसी ग्रेड का कंक्रीट, मसाला, MoRTH का सब-आइटम …) उस पर <i>Show analysis</i> है। Excel की <i>Analysis</i> शीट में हर सब-एनालिसिस अंत में सिर्फ एक बार S-1, S-2 … नंबर से छपता है, और लाइन में लिखा होता है कि कौन सा देखें।</li><li><b>SOR से बड़ा अंतर (MPPWD 2025):</b> जहाँ एक जैसे विवरण वाला MoRTH एनालिसिस SOR रेट से बहुत अलग है, वहाँ खोजते समय <i>Check analysis</i>, जोड़ते समय चेतावनी, और adjustment लाइन हाइलाइट दिखती है। जाँचने के बाद चाहें तो <i>Use the analysis rate without this adjustment</i> चुन सकते हैं।</li></ul>" },
      { en: "<ul><li><b>Items without analysis:</b> Items &amp; measurement shows a note “No rate analysis for this item” with <i>+ Add analysis</i>; Analysis check has <i>Make analysis →</i> which opens the item and <i>← Back to Analysis check</i> to return.</li><li><b>Approval:</b> after adding the lines, click <i>Send to admin for approval</i> (with a note on the source). The super admin sees it in <i>Users → Analysis approvals</i> (orange dot on the Users tab), checks the lines and clicks <i>Approve</i>. From then on it is the item's analysis for everyone.</li><li>An approved analysis always shows “Not from the SOR — drafted copy, analysed by admin. Please check.” in the app. This note is <b>not</b> printed in the Excel export. The admin can remove an approved analysis; the item then uses its SOR rate again.</li></ul>",
        hi: "<ul><li><b>बिना एनालिसिस वाले आइटम:</b> Items &amp; measurement में “No rate analysis for this item” सूचना और <i>+ Add analysis</i> बटन आता है; Analysis check में <i>Make analysis →</i> से आइटम खुलता है और <i>← Back to Analysis check</i> से वापस आते हैं।</li><li><b>अप्रूवल:</b> लाइनें जोड़ने के बाद <i>Send to admin for approval</i> दबाएँ (स्रोत का नोट लिखें)। सुपर एडमिन को यह <i>Users → Analysis approvals</i> में दिखता है (Users टैब पर नारंगी बिंदु); जाँच कर <i>Approve</i> करने पर यह सबके लिए उस आइटम का एनालिसिस बन जाता है।</li><li>अप्रूव एनालिसिस पर ऐप में हमेशा “Not from the SOR — drafted copy, analysed by admin. Please check.” लिखा रहता है। यह सूचना Excel export में <b>नहीं</b> छपती। एडमिन इसे हटा सकता है, तब आइटम फिर SOR रेट पर आ जाता है।</li></ul>" },
    ] },
    { id: "mp25", t: { en: "18. MPPWD Road & Bridge SOR 2025 with MoRTH SDB 2019 analysis", hi: "18. MPPWD रोड व ब्रिज SOR 2025 और MoRTH SDB 2019 एनालिसिस" }, b: [
      { en: "<ul><li>All 2,682 items of the SOR in force from 11.04.2025 (chapters 1–22). About 960 road / bridge items carry the MoRTH Standard Data Book 2019 analysis matched by description (small-project quantities; overheads 12% + profit 10% roads, 20% + 10% bridges, 30% + 10% rehabilitation; plant to site 10 km).</li><li>Basic rates are at the SOR 2025 price level; change any labour, machinery or material rate in <i>Basic rates → MPPWD SOR 2025</i> and every item using it is re-priced (concrete through its MoRTH sub-analysis).</li><li>Electrical (ch. 21), laboratory (ch. 22), survey, video and supply items carry the SOR rate only. The 2017 book is still there for old estimates.</li></ul>",
        hi: "<ul><li>11.04.2025 से लागू SOR के सभी 2,682 आइटम (अध्याय 1–22)। लगभग 960 रोड / ब्रिज आइटम में विवरण के अनुसार मिलाया गया MoRTH Standard Data Book 2019 एनालिसिस है (small project quantity; overhead 12% + profit 10% रोड, 20% + 10% ब्रिज, 30% + 10% rehabilitation; plant से site 10 km)।</li><li>बेसिक रेट SOR 2025 स्तर पर हैं; <i>Basic rates → MPPWD SOR 2025</i> में कोई भी labour, machinery या material रेट बदलें, उसका उपयोग करने वाले सभी आइटम का रेट बदल जाएगा (कंक्रीट उसके MoRTH sub-analysis से)।</li><li>Electrical (अध्याय 21), laboratory (22), survey, video और supply आइटम में सिर्फ़ SOR रेट है। पुराने एस्टीमेट के लिए 2017 की बुक भी उपलब्ध है।</li></ul>" }
    ] },
    { id: "em22", t: { en: "18A. CPWD DSR (E&M) 2022 with DAR (E&M) 2022", hi: "18A. CPWD DSR (E&M) 2022 और DAR (E&M) 2022" }, b: [
      { en: "<ul><li>1,190 priced items of the Delhi Schedule of Rates (E&amp;M) 2022, chapters 1–19 (wiring, MCB/DB, rising mains, cable trays, earthing, cables and jointing, poles and overhead lines, civil items, HVAC plumbing/ducting/AHU, fire alarm, wet riser &amp; sprinkler, BLDC fans), with Correction Slip No. 1 rates.</li><li>980 items carry their DAR (E&amp;M) 2022 analysis: materials with ICD codes + 1% cartage, labour, 12% GST (multiplying factor 0.1405), 15% overheads &amp; profit. The items in Correction Slip No. 1 of the AOR use the corrected analysis.</li><li>Change a labour or material rate in <i>Basic rates → CPWD DSR (E&amp;M) 2022</i> and every E&amp;M item using it is re-priced. Items marked “Rate to be taken from Civil DSR” are not listed; take them from the civil DSR.</li></ul>",
        hi: "<ul><li>Delhi Schedule of Rates (E&amp;M) 2022 के 1,190 रेट वाले आइटम, अध्याय 1–19 (वायरिंग, MCB/DB, राइज़िंग मेन्स, केबल ट्रे, अर्थिंग, केबल व जॉइंटिंग, पोल व ओवरहेड लाइन, सिविल आइटम, HVAC, फायर अलार्म, वेट राइज़र व स्प्रिंकलर, BLDC पंखे), Correction Slip No. 1 के रेट के साथ।</li><li>980 आइटम में DAR (E&amp;M) 2022 का एनालिसिस है: ICD कोड वाला मटीरियल + 1% कार्टेज, लेबर, 12% GST (MF 0.1405), 15% ओवरहेड व प्रॉफिट। AOR के Correction Slip No. 1 वाले आइटम में सुधरा हुआ एनालिसिस है।</li><li><i>Basic rates → CPWD DSR (E&amp;M) 2022</i> में लेबर या मटीरियल रेट बदलें, उसे इस्तेमाल करने वाले सभी E&amp;M आइटम का रेट बदल जाएगा। “Rate to be taken from Civil DSR” वाले आइटम सूची में नहीं हैं; उन्हें सिविल DSR से लें।</li></ul>" }
    ] },
    { id: "workflow", t: { en: "18B. Check & approval (JE → AE → EE), versions and history", hi: "18B. जाँच और स्वीकृति (JE → AE → EE), वर्ज़न और हिस्ट्री" }, b: [
      { en: "<ul><li><b>Designations:</b> the super admin (Users → Groups) or the group admin (Users → My group) sets JE / AE / EE / SE / CE for each member. (A one-time database update, <code>supabase/workflow.sql</code>, must be run by the super admin.)</li><li><b>Send for review:</b> in the estimate open <i>Versions &amp; review</i>, choose the officer and click <i>Send for review</i>. A version (v1, v2…) is saved with the rates and amounts as they are now, and the officer sees exactly that version.</li><li><b>Checking officer:</b> the <i>Reviews</i> tab shows a count of estimates waiting. Open one, type remarks against any item and an overall remark, then <i>Recommend &amp; forward</i> to the next level, <i>Return with remarks</i> (to the JE or to anyone who handled it before) or <i>Approve (final)</i>. <i>Open editable copy</i> puts a copy in your own Estimates to check measurements in detail.</li><li><b>Returned:</b> the JE sees all remarks in the timeline, corrects the estimate and clicks <i>Send corrected version</i>. The officer gets <i>What changed since v1</i> automatically.</li><li><b>Approved:</b> a green bar shows who approved which version. If the estimate is changed later, the bar warns “Changed after approval” with both totals.</li><li><b>Versions:</b> <i>Save version now</i> any time (e.g. before big changes); <i>Restore</i> takes the estimate back to a version (the present state is saved first); <i>Compare two versions</i> shows items added, removed and changed with quantity, rate and amount differences.</li><li><b>History:</b> every change of item, quantity, rate, GST is recorded with the person and time a few seconds after the edit. Rate changes of these items in the rate library, group rates and your own rates are listed below it.</li></ul>",
        hi: "<ul><li><b>पद (Designation):</b> सुपर एडमिन (Users → Groups) या ग्रुप एडमिन (Users → My group) हर सदस्य का JE / AE / EE / SE / CE तय करता है। (सुपर एडमिन को एक बार <code>supabase/workflow.sql</code> चलाना होगा।)</li><li><b>जाँच के लिए भेजना:</b> एस्टीमेट में <i>Versions &amp; review</i> खोलें, अधिकारी चुनें और <i>Send for review</i> दबाएँ। उस समय के रेट और राशि के साथ एक वर्ज़न (v1, v2…) सेव होता है और अधिकारी को वही वर्ज़न दिखता है।</li><li><b>जाँच अधिकारी:</b> <i>Reviews</i> टैब पर प्रतीक्षा वाले एस्टीमेट की संख्या दिखती है। खोलें, किसी भी आइटम पर टिप्पणी और कुल टिप्पणी लिखें, फिर <i>Recommend &amp; forward</i> (अगले स्तर पर), <i>Return with remarks</i> (JE या पहले देख चुके अधिकारी को) या <i>Approve (final)</i> दबाएँ। <i>Open editable copy</i> से आपकी Estimates में एक कॉपी आ जाती है ताकि नाप विस्तार से जाँच सकें।</li><li><b>लौटाया गया:</b> JE को टाइमलाइन में सारी टिप्पणियाँ दिखती हैं; सुधार कर <i>Send corrected version</i> दबाएँ। अधिकारी को <i>What changed since v1</i> अपने आप दिखता है।</li><li><b>स्वीकृत:</b> हरी पट्टी में किसने कौन सा वर्ज़न approve किया दिखता है। बाद में बदलाव हो तो “Changed after approval” और दोनों टोटल दिखते हैं।</li><li><b>वर्ज़न:</b> कभी भी <i>Save version now</i>; <i>Restore</i> से पुराने वर्ज़न पर लौटें (मौजूदा हालत पहले सेव होती है); <i>Compare two versions</i> में जोड़े, हटाए और बदले आइटम, मात्रा-रेट-राशि का अंतर दिखता है।</li><li><b>हिस्ट्री:</b> आइटम, मात्रा, रेट, GST का हर बदलाव व्यक्ति और समय के साथ कुछ सेकंड में दर्ज होता है। इन आइटमों के लाइब्रेरी, ग्रुप और निजी रेट के बदलाव नीचे दिखते हैं।</li></ul>" } ] },
    { id: "cad", t: { en: "18E. CAD Studio — 2D drafting, DXF / PDF, take-off", hi: "18E. CAD Studio — 2D ड्राफ्टिंग, DXF / PDF, टेक-ऑफ" }, b: [
      { en: "<ul><li><b>Open:</b> CAD Studio tab → <i>+ New drawing</i> (choose mm, m or feet-inches and the drawing scale), <i>Import DXF</i> or <i>Import PDF</i>. DWG files: save them as DXF first (AutoCAD <i>Save As DXF</i>, or the free <i>ODA File Converter</i>). Design Studio drawings open here with <i>✏️ Open in CAD Studio</i>.</li><li><b>Draw like AutoCAD:</b> use the ribbon or type a command and press Enter — L (line), PL (polyline, with Arc / Width), REC, C, A, POL, EL, SPL, XL, T / MT (text), H (hatch: click inside an area), BO (boundary), B / I (blocks). Modify: M, CO, RO, SC (Reference = calibrate), MI, O, TR, EX, F, CHA, AR, S, BR, J, X, MA, E. Dimensions: DLI, DAL, DCO, DBA, DAN, DRA, DDI, DOR, LE.</li><li><b>Precise input:</b> type <code>x,y</code>, <code>@dx,dy</code>, <code>@length&lt;angle</code>, or just a length (the direction follows the cursor / ortho / polar). Lengths can be <code>3.5m</code>, <code>230mm</code>, <code>12'6&quot;</code>. Snaps (endpoint, midpoint, centre, intersection, perpendicular, tangent, quadrant…) show a yellow marker; F3 snaps, F8 ortho, F10 polar, F11 tracking. Ctrl+Z / Ctrl+Y undo / redo; Space repeats the last command; Esc cancels.</li><li><b>Layers & properties:</b> the side panel shows Properties (edit coordinates, length, radius, text, hatch pattern…), Layers (on/off, freeze, lock, colour, linetype, lineweight, current), Blocks and Settings (display unit, dimension style, snaps, background). Changing the display unit never changes the real size.</li><li><b>Trace a drawing:</b> File → Attach image or Attach PDF. A CAD-made PDF can come in as <b>vectors</b> (real lines you can snap to); a scan comes in as an image. Set the true size with SCALE → select → base point → Reference → pick a known dimension → type its real length.</li><li><b>Take-off:</b> Measure → <i>Take-off → estimate</i> (TO). Pick objects (length / area / count), click inside rooms (area), or click points. Choose the estimate and item; for cum items give the thickness / depth (area × depth) or width × depth (length); for kg items give kg per metre. A measurement row is added with “📐 From drawing …”.</li><li><b>Output:</b> File → Export DXF (opens in AutoCAD, BricsCAD, LibreCAD, QCAD), Plot PDF sheet (A4–A0, scale 1:N or fit, title block, black & white or colour), Export PNG. Save as revision keeps R1, R2…; drawings are saved on the device at once and in the cloud (supabase/cad.sql).</li></ul>",
        hi: "<ul><li><b>खोलें:</b> CAD Studio टैब → <i>+ New drawing</i> (mm, m या फ़ीट-इंच और ड्रॉइंग स्केल चुनें), <i>Import DXF</i> या <i>Import PDF</i>। DWG फ़ाइल पहले DXF में सेव करें (AutoCAD में <i>Save As DXF</i>, या मुफ़्त <i>ODA File Converter</i>)। Design Studio की ड्रॉइंग <i>✏️ Open in CAD Studio</i> से यहाँ खुलती है।</li><li><b>AutoCAD जैसा ड्रॉ करें:</b> रिबन से या कमांड टाइप करके Enter दबाएँ — L, PL, REC, C, A, POL, EL, SPL, XL, T/MT, H (एरिया के अंदर क्लिक), BO, B/I। बदलाव: M, CO, RO, SC, MI, O, TR, EX, F, CHA, AR, S, BR, J, X, MA, E। डाइमेंशन: DLI, DAL, DCO, DBA, DAN, DRA, DDI, DOR, LE।</li><li><b>सटीक इनपुट:</b> <code>x,y</code>, <code>@dx,dy</code>, <code>@लंबाई&lt;कोण</code> या सिर्फ़ लंबाई टाइप करें। <code>3.5m</code>, <code>230mm</code>, <code>12'6&quot;</code> सब चलता है। स्नैप पीले निशान से दिखते हैं; F3 स्नैप, F8 ortho, F10 polar, F11 tracking। Ctrl+Z / Ctrl+Y undo / redo; Space पिछली कमांड दोहराता है; Esc रद्द करता है।</li><li><b>लेयर और प्रॉपर्टी:</b> साइड पैनल में Properties (कोऑर्डिनेट, लंबाई, रेडियस, टेक्स्ट, हैच…), Layers (on/off, freeze, lock, रंग, लाइनटाइप, मोटाई), Blocks और Settings (यूनिट, डाइमेंशन स्टाइल, स्नैप)। डिस्प्ले यूनिट बदलने से असली साइज़ नहीं बदलता।</li><li><b>ड्रॉइंग ट्रेस करें:</b> File → Attach image या Attach PDF। CAD से बनी PDF <b>vectors</b> (असली लाइनें) के रूप में आ सकती है; स्कैन इमेज के रूप में। असली साइज़: SCALE → चुनें → बेस पॉइंट → Reference → ज्ञात नाप के दो पॉइंट → असली लंबाई टाइप करें।</li><li><b>टेक-ऑफ:</b> Measure → <i>Take-off → estimate</i> (TO)। ऑब्जेक्ट चुनें (लंबाई / एरिया / गिनती), कमरों के अंदर क्लिक करें (एरिया) या पॉइंट चुनें। एस्टीमेट और आइटम चुनें; cum आइटम के लिए मोटाई / गहराई या चौड़ाई × गहराई दें; kg आइटम के लिए kg प्रति मीटर। “📐 From drawing …” वाली मेज़रमेंट रो जुड़ जाती है।</li><li><b>आउटपुट:</b> File → Export DXF, Plot PDF sheet (A4–A0, स्केल 1:N, टाइटल ब्लॉक), Export PNG। Save as revision से R1, R2… बनते हैं; ड्रॉइंग तुरंत डिवाइस पर और क्लाउड में सेव होती है (supabase/cad.sql)।</li></ul>" } ] },
    { id: "mep", t: { en: "18E-2. Electrical and plumbing drawings", hi: "18E-2. इलेक्ट्रिकल और प्लंबिंग ड्रॉइंग" }, b: [
      { en: "<ul><li><b>Electrical:</b> place lights, fans, switch boards, sockets and a distribution board with <i>Site &amp; services → Library item</i>. <i>Electrical settings</i> (<code>ELECSET</code>) turns the electrical layout on: IS symbols on the plan, and CPWD DSR (E&amp;M) 2022 point wiring by building group (A: Type I–III quarters, B: Type IV and above, C: non-residential), PVC or steel conduit, modular or piano switches.</li><li><i>Auto wiring</i> (<code>WIREAUTO</code>) joins every point to the switch board of its room, the boards to the DB in circuits of not more than 10 points / 800 W, and each 16 A socket on its own circuit. <i>Wire / circuit</i> (<code>WIRE</code>) draws them by hand.</li><li>Quantities: each point as point wiring; 6 A and 16 A socket boxes; circuit and power wiring in metres (run plus the drops to each board); MCB DB by ways, MCBs, incomer, RCCB, earth pits.</li><li><b>Plumbing:</b> <i>Plumbing pipe</i> (<code>PLUMB</code>) — cold / hot water (CPVC), soil, waste, vent and rain water (uPVC), drains (S.W.). Each service has its own colour, size label and flow arrows; uPVC bends and tees are counted.</li><li><i>Show layout</i> (<code>MEPVIEW</code>) shows all, only electrical, only plumbing or the building only — the plan, sheets, PDF and DXF follow it. <i>Schedules</i> → Electrical (legend with symbols + DB schedule) or Plumbing (pipe schedule + fittings).</li></ul>",
        hi: "<ul><li><b>इलेक्ट्रिकल:</b> <i>Site &amp; services → Library item</i> से लाइट, पंखा, स्विच बोर्ड, सॉकेट और DB रखें। <i>Electrical settings</i> (<code>ELECSET</code>) से इलेक्ट्रिकल लेआउट चालू होता है: प्लान पर IS चिह्न, और CPWD DSR (E&amp;M) 2022 की पॉइंट वायरिंग — ग्रुप A (Type I–III क्वार्टर), B (Type IV और ऊपर), C (गैर-आवासीय), PVC या स्टील कंड्यूट, मॉड्यूलर या पियानो स्विच।</li><li><i>Auto wiring</i> (<code>WIREAUTO</code>) हर पॉइंट को उसके कमरे के स्विच बोर्ड से, और बोर्डों को DB से जोड़ता है — एक सर्किट में 10 पॉइंट / 800 W से ज़्यादा नहीं, और हर 16 A सॉकेट अलग सर्किट पर। <i>Wire / circuit</i> (<code>WIRE</code>) से हाथ से भी जोड़ सकते हैं।</li><li>मात्रा: हर पॉइंट की पॉइंट वायरिंग; 6 A और 16 A सॉकेट बॉक्स; सर्किट और पावर वायरिंग मीटर में (बोर्ड तक नीचे आने वाली लंबाई सहित); DB (ways के हिसाब से), MCB, इनकमर, RCCB, अर्थ पिट।</li><li><b>प्लंबिंग:</b> <i>Plumbing pipe</i> (<code>PLUMB</code>) — ठंडा / गरम पानी (CPVC), सॉइल, वेस्ट, वेंट और बारिश का पानी (uPVC), बाहर की नाली (S.W.)। हर सेवा का अपना रंग, साइज़ और बहाव के तीर; uPVC के बेंड और टी गिने जाते हैं।</li><li><i>Show layout</i> (<code>MEPVIEW</code>) — सब, सिर्फ़ इलेक्ट्रिकल, सिर्फ़ प्लंबिंग या सिर्फ़ बिल्डिंग; प्लान, शीट, PDF और DXF वैसा ही दिखाते हैं। <i>Schedules</i> → Electrical (चिह्नों वाला लेजेंड + DB शेड्यूल) या Plumbing (पाइप शेड्यूल + फ़िटिंग)।</li></ul>" }
    ] },
    { id: "bim", t: { en: "18F. Building model (BIM), 3D view and quantities to estimate", hi: "18F. बिल्डिंग मॉडल (BIM), 3D व्यू और मात्रा सीधे एस्टीमेट में" }, b: [
      { en: "<ul><li><b>Levels:</b> pick the level at the top (Ground / First / Roof — add or change heights in the <i>Building</i> side tab). New elements go on the current level.</li><li><b>Walls:</b> ribbon <i>Building → Wall</i> (or type <code>WALL</code>). Click the points; type a length like <code>4000</code> or <code>@4000,0</code>. Choose <i>Close</i> to make a closed outline — those walls are marked exterior (outside plaster and paint). Thickness, height and material (brick / block / stone / RCC) are set in the Building tab or the Properties of a selected wall. Corners and T-junctions join automatically.</li><li><b>Doors / windows / openings:</b> click on a wall; they cut the wall in plan and 3D and are deducted from masonry, plaster and paint. Lintels are added over them.</li><li><b>Slab, column, beam, footing, roof, stair, railing:</b> from the same ribbon group. <i>Footing → Columns</i> puts a footing under every column. Roof can be flat, shed, gable or hip.</li><li><b>Room:</b> click inside a space bounded by walls — the room gets its name, floor finish and area (floor, skirting, ceiling plaster and paint are measured).</li><li><b>3D:</b> <i>3D: split</i> or full screen. Drag to orbit, right-drag / two fingers to pan, wheel to zoom. Buttons: Iso, Top, Front…, Shadows, Edges, Parallel, Cut (section by height), Sun, Levels, PNG.</li><li><b>Quantities:</b> <i>Σ Quantities</i> lists each work with zone (up to plinth / above plinth), model quantity, suggested DSOR 2023 item, rate and amount. Change any item with <i>Change</i>, untick what you do not need, choose estimate and part, then <i>Send / update estimate</i>. Rows come into the measurement sheet marked <i>From drawing</i>; sending again after changing the model replaces only those rows and the <i>In estimate</i> column shows the difference.</li><li><b>Rules:</b> deductions follow IS 1200 style rules (openings up to 0.1 m² not deducted from masonry, up to 0.5 m² not from plaster — change in the Building tab). Reinforcement is a thumb rule in kg/m³ until a BBS is attached; check it.</li><li>The model is saved inside the drawing (on this device and in the cloud). No extra database step is needed beyond <code>supabase/cad.sql</code>.</li></ul>",
        hi: "<ul><li><b>लेवल:</b> ऊपर लेवल चुनें (Ground / First / Roof — ऊँचाई बदलनी या नया लेवल जोड़ना हो तो साइड में <i>Building</i> टैब)। नए एलिमेंट चालू लेवल पर बनते हैं।</li><li><b>दीवार:</b> रिबन <i>Building → Wall</i> (या <code>WALL</code> टाइप करें)। पॉइंट क्लिक करें; लंबाई <code>4000</code> या <code>@4000,0</code> टाइप कर सकते हैं। <i>Close</i> चुनने पर बंद आउटलाइन बनती है — वे दीवारें बाहरी मानी जाती हैं (बाहर का प्लास्टर और पेंट)। मोटाई, ऊँचाई और मटेरियल (ईंट / ब्लॉक / पत्थर / RCC) Building टैब में या चुनी हुई दीवार की Properties में। कोने और T-जोड़ अपने-आप जुड़ते हैं।</li><li><b>दरवाज़ा / खिड़की / ओपनिंग:</b> दीवार पर क्लिक करें; प्लान और 3D में दीवार कटती है और चिनाई, प्लास्टर, पेंट से घटती है। ऊपर लिंटल अपने-आप जुड़ता है।</li><li><b>स्लैब, कॉलम, बीम, फ़ुटिंग, छत, सीढ़ी, रेलिंग:</b> इसी रिबन ग्रुप से। <i>Footing → Columns</i> हर कॉलम के नीचे फ़ुटिंग बना देता है। छत flat, shed, gable या hip हो सकती है।</li><li><b>कमरा (Room):</b> दीवारों से घिरी जगह के अंदर क्लिक करें — नाम, फ़्लोर फ़िनिश और एरिया आता है (फ़र्श, स्कर्टिंग, छत प्लास्टर व पेंट की मात्रा बनती है)।</li><li><b>3D:</b> <i>3D: split</i> या पूरी स्क्रीन। घुमाने के लिए ड्रैग, खिसकाने के लिए राइट-ड्रैग / दो उँगली, ज़ूम के लिए व्हील। बटन: Iso, Top, Front…, Shadows, Edges, Parallel, Cut (ऊँचाई से सेक्शन), Sun, Levels, PNG।</li><li><b>मात्रा (Quantities):</b> <i>Σ Quantities</i> में हर काम, ज़ोन (प्लिंथ तक / प्लिंथ के ऊपर), मॉडल की मात्रा, सुझाया DSOR 2023 आइटम, रेट और राशि दिखती है। <i>Change</i> से आइटम बदलें, जो नहीं चाहिए उसका टिक हटाएँ, एस्टीमेट और पार्ट चुनें, फिर <i>Send / update estimate</i>। मेज़रमेंट शीट में पंक्तियाँ <i>From drawing</i> लिखी आती हैं; मॉडल बदलकर दोबारा भेजने पर सिर्फ़ वही पंक्तियाँ बदलती हैं और <i>In estimate</i> कॉलम में अंतर दिखता है।</li><li><b>नियम:</b> कटौती IS 1200 जैसे नियम से (चिनाई में 0.1 m² तक और प्लास्टर में 0.5 m² तक की ओपनिंग नहीं घटती — Building टैब में बदल सकते हैं)। सरिया अभी thumb rule (kg/m³) से है, BBS जुड़ने तक इसे जाँच लें।</li><li>मॉडल ड्रॉइंग के अंदर ही सेव होता है (डिवाइस और क्लाउड दोनों में)। <code>supabase/cad.sql</code> के अलावा कोई नया डेटाबेस स्टेप नहीं।</li></ul>" }
    ] },
    { id: "look3d", t: { en: "18G. 3D materials, sun by date and time, scenes and render", hi: "18G. 3D मटेरियल, तारीख-समय से सूरज, सीन और रेंडर" }, b: [
      { en: "<ul><li><b>Materials:</b> CAD Studio → side tab <i>Building</i> → <i>3D materials</i>. Choose the look and colour of outer walls, inner walls, columns and beams, slabs, ceilings, roofs, doors, windows, glass, stairs, railings and ground (paint shades, exposed brick, block, stone, concrete, vitrified / ceramic / Kota / granite / marble, wood, metal sheets, clay tiles, grass, pavers…). One element can be different: select it → Properties → <i>3D look</i>. Room floors follow their floor finish. Looks only change the picture — quantities and SOR items stay the same.</li><li><b>Style:</b> in the 3D bar choose <i>Realistic</i> (patterns), <i>Colours</i> (plain colours) or <i>White model</i> (for presentations).</li><li><b>Sun:</b> <i>☀ Sun</i> → <i>Date and time</i> gives the real sun for the site (latitude, longitude and true north are in the Building tab; default Bilaspur, IST). Use 21 June / 21 December and the time slider for shadow studies, or set the sun by hand. Sky, haze and shadows can be switched on or off.</li><li><b>Scenes:</b> <i>🎬 Scenes</i> → type a name → <i>Save view</i>. The camera, style, cut, levels and sun are kept with the drawing; click a scene to go back to it.</li><li><b>Render:</b> <i>📷 Render</i> → choose the size (HD, Full HD, 4K, A4 300 dpi) → <i>Render</i> → <i>Download PNG</i>. It uses a bigger shadow map, soft shadows and smoothing. It is a high-quality real-time picture — not ray-traced photo-realism (planned later). Indoor lights are not modelled yet.</li></ul>",
        hi: "<ul><li><b>मटेरियल:</b> CAD Studio → साइड टैब <i>Building</i> → <i>3D materials</i>। बाहरी दीवार, अंदर की दीवार, कॉलम-बीम, स्लैब, सीलिंग, छत, दरवाज़े, खिड़की, काँच, सीढ़ी, रेलिंग और ज़मीन का लुक व रंग चुनें (पेंट के रंग, खुली ईंट, ब्लॉक, पत्थर, कंक्रीट, विट्रीफ़ाइड / सिरेमिक / कोटा / ग्रेनाइट / मार्बल, लकड़ी, मेटल शीट, खपरैल, घास, पेवर…)। किसी एक एलिमेंट को अलग रखना हो तो उसे चुनें → Properties → <i>3D look</i>। कमरे का फ़र्श उसकी floor finish से आता है। लुक सिर्फ़ तस्वीर बदलता है — मात्रा और SOR आइटम वही रहते हैं।</li><li><b>स्टाइल:</b> 3D बार में <i>Realistic</i> (पैटर्न), <i>Colours</i> (सादे रंग) या <i>White model</i> (प्रेज़ेंटेशन के लिए)।</li><li><b>सूरज:</b> <i>☀ Sun</i> → <i>Date and time</i> से साइट का असली सूरज आता है (अक्षांश, देशांतर और true north Building टैब में; डिफ़ॉल्ट बिलासपुर, IST)। छाया देखने के लिए 21 June / 21 December और समय की स्लाइडर चलाएँ, या सूरज हाथ से सेट करें। Sky, haze और shadows चालू-बंद कर सकते हैं।</li><li><b>सीन:</b> <i>🎬 Scenes</i> → नाम लिखें → <i>Save view</i>। कैमरा, स्टाइल, कट, लेवल और सूरज ड्रॉइंग के साथ सेव होते हैं; सीन पर क्लिक करते ही वही व्यू आ जाता है।</li><li><b>रेंडर:</b> <i>📷 Render</i> → साइज़ चुनें (HD, Full HD, 4K, A4 300 dpi) → <i>Render</i> → <i>Download PNG</i>। इसमें बड़ा shadow map, नरम छाया और smoothing होती है। यह अच्छी क्वालिटी की real-time तस्वीर है — ray-traced फ़ोटो जैसी नहीं (वह बाद में)। कमरे की बिजली की लाइटें अभी नहीं हैं।</li></ul>" }
    ] },
    { id: "rebar3d", t: { en: "18H. Reinforcement bars in the model, 3D rebar and BBS", hi: "18H. मॉडल में सरिया, 3D रीबार और BBS" }, b: [
      { en: "<ul><li><b>Add bars:</b> ribbon <i>Building → Rebar</i> (or type <code>REBAR</code>) adds starting reinforcement to every column, beam, footing and slab (or only to the selected ones). Building tab → <i>Add bars to all</i> does the same. One element: select it → Properties → <i>Add reinforcement</i>.</li><li><b>Change bars:</b> in Properties set cover, number and diameter of main bars, ties / stirrups and spacing; footing and slab mesh diameter and spacing. Each element shows its bar list, kg, kg/m³, % of concrete and the IS 456 minimum / maximum check. Steel grade and concrete (for the lap length) are in the Building tab.</li><li><b>Rules:</b> 90° bend 2d, stirrup / tie = 2(A+B) + 2 hooks max(10d, 75 mm) − 12d, lap max(Ld, 30d) (Fe500D M25 = 49d), laps for bars over 12 m. Column bars go into the footing with an L-leg, lap into the column above, or end with a leg at the top floor. Beam bars have 90° legs at both ends. Slabs: bottom mesh only — add top / extra bars in the estimate's BBS.</li><li><b>3D:</b> press <i>⛓ Rebar</i> in the 3D bar — concrete becomes see-through and bars are coloured by diameter (8 yellow, 10 green, 12 blue, 16 red, 20 purple, 25 orange).</li><li><b>BBS:</b> ribbon <i>BBS</i> (or Building tab → <i>Bar bending schedule</i>) lists member, mark, diameter, nos, cut length, total, kg and how each cut length was found; totals by diameter and up to / above plinth; CSV download.</li><li><b>Estimate:</b> <i>Σ Quantities</i> now takes steel from the bars (\"from bars / BBS\"); <i>Send / update estimate</i> puts them in the steel item as BBS rows with the same weight. Elements without bars still use the thumb rule.</li><li>These are starting values, not a structural design — the engineer must check them against the approved drawings.</li></ul>",
        hi: "<ul><li><b>सरिया जोड़ें:</b> रिबन <i>Building → Rebar</i> (या <code>REBAR</code> टाइप करें) हर कॉलम, बीम, फ़ुटिंग और स्लैब में (या सिर्फ़ चुने हुए में) शुरुआती सरिया डाल देता है। Building टैब → <i>Add bars to all</i> भी यही करता है। एक एलिमेंट के लिए: उसे चुनें → Properties → <i>Add reinforcement</i>।</li><li><b>सरिया बदलें:</b> Properties में cover, मेन बार की संख्या और व्यास, टाई / स्टिरप और उनकी दूरी; फ़ुटिंग और स्लैब की जाली का व्यास और दूरी। हर एलिमेंट में बार की सूची, kg, kg/m³, कंक्रीट का % और IS 456 की न्यूनतम / अधिकतम जाँच दिखती है। स्टील ग्रेड और कंक्रीट (लैप के लिए) Building टैब में।</li><li><b>नियम:</b> 90° मोड़ 2d, स्टिरप / टाई = 2(A+B) + 2 हुक max(10d, 75 mm) − 12d, लैप max(Ld, 30d) (Fe500D M25 = 49d), 12 m से लंबे बार में लैप। कॉलम के बार L-लेग के साथ फ़ुटिंग में जाते हैं, ऊपर के कॉलम में लैप होते हैं, या सबसे ऊपर की मंज़िल पर लेग से खत्म होते हैं। बीम के बार के दोनों सिरों पर 90° लेग। स्लैब: सिर्फ़ नीचे की जाली — ऊपर / अतिरिक्त बार एस्टीमेट की BBS में जोड़ें।</li><li><b>3D:</b> 3D बार में <i>⛓ Rebar</i> दबाएँ — कंक्रीट पारदर्शी हो जाता है और बार व्यास के हिसाब से रंगीन दिखते हैं (8 पीला, 10 हरा, 12 नीला, 16 लाल, 20 बैंगनी, 25 नारंगी)।</li><li><b>BBS:</b> रिबन में <i>BBS</i> (या Building टैब → <i>Bar bending schedule</i>) में मेंबर, मार्क, व्यास, संख्या, कट लंबाई, कुल, kg और हर कट लंबाई कैसे निकली — सब दिखता है; व्यास के हिसाब से और प्लिंथ तक / ऊपर का जोड़; CSV डाउनलोड।</li><li><b>एस्टीमेट:</b> <i>Σ Quantities</i> अब स्टील बार से लेता है (\"from bars / BBS\"); <i>Send / update estimate</i> इन्हें स्टील आइटम में BBS पंक्तियों के रूप में उसी वज़न के साथ डालता है। जिन एलिमेंट में बार नहीं हैं, उनमें अब भी thumb rule।</li><li>ये शुरुआती मान हैं, स्ट्रक्चरल डिज़ाइन नहीं — इंजीनियर स्वीकृत ड्रॉइंग से ज़रूर मिलाएँ।</li></ul>" }
    ] },
    { id: "road", t: { en: "18I. Roads, earthwork (cut / fill), L-section, cross-sections and culverts", hi: "18I. सड़क, अर्थवर्क (कटिंग / फ़िलिंग), L-सेक्शन, क्रॉस-सेक्शन और कल्वर्ट" }, b: [
      { en: "<ul><li><b>Road:</b> ribbon <i>Roads &amp; earthwork → Road</i> (or <code>ROAD</code>): click the centre line points (or <i>Object</i> to use an existing polyline — arcs are followed in 2 m chords), press Enter, then give the start chainage, ground level and road height. The plan shows the carriageway, formation edges, toe / top of slope lines and chainage marks.</li><li><b>Levels &amp; layers:</b> select the road → Properties → <i>Levels &amp; layers…</i>. Paste two columns (chainage, RL in metres; 0+250 style also works) for the surveyed ground levels and for the design road levels (grade points). Set the pavement layers (BC, DBM, WMM, GSB, PQC, DLC, earth) with thickness and width. In Properties set carriageway and shoulder width, camber, shoulder slope, fill and cut side slopes, the section interval and the ground cross slope.</li><li><b>Earthwork:</b> <i>Earthwork</i> shows every section (chainage, NGL, road level, formation, cut and fill area and volume, mass-haul ordinate) with a longitudinal-section and mass-haul chart; CSV download. Volumes use the average end area method; the ground is taken as a straight line across each section (with the cross slope you give).</li><li><b>Drawings:</b> <i>Draw L-section</i> (vertical × 10, with chainage / level / cut-fill table) and <i>Draw cross-sections</i> put real CAD objects below the plan on layers R-LSEC / R-XSEC — plot them with File → Plot.</li><li><b>Culvert:</b> <i>Culvert</i> → click on the road → Pipe (NP4 600 / 1000 / 1200 / 1500 mm, rows) or Box (span × height, cells). Length is toe to toe + 1 m; the invert is at ground level unless you set it; a cushion under 600 mm is flagged.</li><li><b>Quantities:</b> <i>Σ Quantities</i> lists clearing &amp; grubbing, roadway excavation, embankment, earthen shoulders, pavement layers, prime and tack coat, culvert excavation, NP4 pipes, PCC head walls, RCC box and its steel — mapped to MPPWD SOR 2025 (Road &amp; Bridge) items, which you can change — and sends them to the estimate.</li><li>Not yet: horizontal curves with transitions, vertical curves, superelevation, side drains, retaining walls and surveyed cross-section ground (each section uses one cross slope).</li></ul>",
        hi: "<ul><li><b>सड़क:</b> रिबन <i>Roads &amp; earthwork → Road</i> (या <code>ROAD</code>): सेंटर लाइन के पॉइंट क्लिक करें (या पहले से बनी पॉलीलाइन के लिए <i>Object</i> — आर्क 2 m के टुकड़ों में चलता है), Enter दबाएँ, फिर शुरू की chainage, ज़मीन का लेवल और सड़क की ऊँचाई दें। प्लान में कैरिजवे, फ़ॉर्मेशन किनारे, ढलान की toe / top लाइन और chainage निशान दिखते हैं।</li><li><b>लेवल और लेयर:</b> सड़क चुनें → Properties → <i>Levels &amp; layers…</i>। सर्वे के ज़मीन लेवल और डिज़ाइन रोड लेवल के लिए दो कॉलम (chainage, RL मीटर में; 0+250 तरीका भी चलेगा) पेस्ट करें। पेवमेंट लेयर (BC, DBM, WMM, GSB, PQC, DLC, मिट्टी) की मोटाई और चौड़ाई दें। Properties में कैरिजवे व शोल्डर की चौड़ाई, कैम्बर, शोल्डर ढलान, फ़िलिंग व कटिंग की साइड ढलान, सेक्शन की दूरी और ज़मीन का आड़ा ढलान दें।</li><li><b>अर्थवर्क:</b> <i>Earthwork</i> में हर सेक्शन (chainage, NGL, रोड लेवल, फ़ॉर्मेशन, कट व फ़िल का क्षेत्रफल व आयतन, mass-haul) और L-सेक्शन / mass-haul चार्ट; CSV डाउनलोड। आयतन average end area विधि से; हर सेक्शन में ज़मीन एक सीधी लाइन मानी जाती है (आपके दिए आड़े ढलान के साथ)।</li><li><b>ड्रॉइंग:</b> <i>Draw L-section</i> (वर्टिकल × 10, chainage / लेवल / कट-फ़िल टेबल के साथ) और <i>Draw cross-sections</i> प्लान के नीचे R-LSEC / R-XSEC लेयर पर असली CAD ऑब्जेक्ट बनाते हैं — File → Plot से प्रिंट करें।</li><li><b>कल्वर्ट:</b> <i>Culvert</i> → सड़क पर क्लिक → Pipe (NP4 600 / 1000 / 1200 / 1500 mm, पंक्तियाँ) या Box (span × height, cells)। लंबाई toe से toe + 1 m; invert ज़मीन पर, जब तक आप न बदलें; 600 mm से कम cushion पर चेतावनी।</li><li><b>मात्रा:</b> <i>Σ Quantities</i> में clearing &amp; grubbing, सड़क की खुदाई, embankment, मिट्टी के शोल्डर, पेवमेंट लेयर, prime व tack coat, कल्वर्ट खुदाई, NP4 पाइप, PCC head wall, RCC box और उसका स्टील — MPPWD SOR 2025 (Road &amp; Bridge) के आइटम से जुड़े, जिन्हें बदल सकते हैं — और एस्टीमेट में भेजें।</li><li>अभी नहीं: ट्रांज़िशन वाले horizontal curve, vertical curve, superelevation, साइड ड्रेन, रिटेनिंग वॉल और सर्वे वाले क्रॉस-सेक्शन ग्राउंड (हर सेक्शन में एक आड़ा ढलान)।</li></ul>" }
    ] },
    { id: "cadui", t: { en: "18J. CAD Studio screen, full screen, item library, 3D models, GLB / OBJ / IFC export", hi: "18J. CAD Studio स्क्रीन, फ़ुल स्क्रीन, आइटम लाइब्रेरी, 3D मॉडल, GLB / OBJ / IFC एक्सपोर्ट" }, b: [
      { en: "<ul><li><b>Ribbon:</b> tabs at the top — <i>Home</i> (most used: line, polyline, rectangle, move, copy, trim, offset, erase, dimension, text, wall, door, window, slab, column), Draw, Modify, Annotate, Building, Roads &amp; earthwork, Site &amp; services, Block, Measure, View. Each button has an icon; hover shows the typed command.</li><li><b>Full screen:</b> <i>⛶ Full screen</i> at the top right uses the whole screen for drawing (Esc or <i>Exit full screen</i> to return). On a phone the side panel starts closed — open it with <i>☰ Panel</i>.</li><li><b>While drawing:</b> every object appears as soon as it is made (you do not have to leave the command). Slab, roof and stair start with a click — change type, thickness, slope or width with the words shown in the command line (type them or click them). When the command asks a choice that has a default, a click on the drawing accepts the default.</li><li><b>Library:</b> side tab <i>Library</i> (or ribbon <i>Site &amp; services</i>) — trees, palm, shrub, bench, lamp post, street light, manhole, European / Indian WC, wash basin, kitchen sink, floor trap, water tank (litres), light, tube light, fan, switch board, socket, distribution board. Click <i>Place</i>, then click in the drawing (Rotate / Scale in the command line, Enter to finish); <i>3D</i> shows a preview. Lights and fans hang from the ceiling, switch boards / sockets sit on the wall height. Each item is counted in Σ Quantities with a suggested SOR item. <i>Landscape area</i>: lawn, paver blocks, gravel, planting bed, PCC — measured in m².</li><li><b>3D preview of an SOR item:</b> in Σ Quantities press <i>👁 3D</i> on a row to see exactly which elements make that quantity.</li><li><b>Your 3D models:</b> File → <i>Import 3D model (GLB / glTF)</i>. Colours are kept, textures become plain colours; Draco-compressed files are not supported. The model is saved with the drawing; set scale, rotation and height in Properties.</li><li><b>Export:</b> File → <i>Export 3D model — GLB</i> (Windows 3D Viewer, Blender, online viewers), <i>OBJ + MTL</i> (zip), <i>Export BIM model — IFC4</i> (Revit, ArchiCAD, BIMcollab, IFC viewers) with storeys, element types, colours and the quantities used in the estimate. The IFC uses triangulated shapes (not editable parametric walls in other software); openings are cut in the wall shapes.</li></ul>",
        hi: "<ul><li><b>रिबन:</b> ऊपर टैब — <i>Home</i> (सबसे ज़्यादा काम आने वाले: line, polyline, rectangle, move, copy, trim, offset, erase, dimension, text, wall, door, window, slab, column), Draw, Modify, Annotate, Building, Roads &amp; earthwork, Site &amp; services, Block, Measure, View। हर बटन पर आइकन है; माउस रखने पर command का नाम दिखता है।</li><li><b>फ़ुल स्क्रीन:</b> ऊपर दाएँ <i>⛶ Full screen</i> से पूरी स्क्रीन ड्रॉइंग के लिए (वापस आने के लिए Esc या <i>Exit full screen</i>)। फ़ोन पर साइड पैनल बंद रहता है — <i>☰ Panel</i> से खोलें।</li><li><b>ड्रॉ करते समय:</b> हर ऑब्जेक्ट बनते ही दिखता है (command से बाहर आने की ज़रूरत नहीं)। Slab, roof और stair सीधे क्लिक से शुरू होते हैं — टाइप, मोटाई, ढलान या चौड़ाई command line में दिखे शब्दों से बदलें। जब command कोई विकल्प default के साथ पूछे, तो ड्रॉइंग पर क्लिक करने से default मान लिया जाता है।</li><li><b>लाइब्रेरी:</b> साइड टैब <i>Library</i> (या रिबन <i>Site &amp; services</i>) — पेड़, ताड़, झाड़ी, बेंच, लैम्प पोस्ट, स्ट्रीट लाइट, मैनहोल, European / Indian WC, वॉश बेसिन, किचन सिंक, फ़्लोर ट्रैप, पानी की टंकी (लीटर), लाइट, ट्यूब लाइट, पंखा, स्विच बोर्ड, सॉकेट, DB। <i>Place</i> दबाएँ, फिर ड्रॉइंग में क्लिक करें (Rotate / Scale command line में, Enter से खत्म); <i>3D</i> से झलक। लाइट और पंखे छत से लटकते हैं, स्विच बोर्ड / सॉकेट दीवार की ऊँचाई पर। हर आइटम Σ Quantities में SOR आइटम के साथ गिना जाता है। <i>Landscape area</i>: लॉन, पेवर ब्लॉक, गिट्टी, पौधों की क्यारी, PCC — m² में।</li><li><b>SOR आइटम की 3D झलक:</b> Σ Quantities में किसी पंक्ति पर <i>👁 3D</i> दबाएँ — दिखेगा कि वह मात्रा किन एलिमेंट से बनी।</li><li><b>अपने 3D मॉडल:</b> File → <i>Import 3D model (GLB / glTF)</i>। रंग बने रहते हैं, texture सादे रंग में; Draco-compressed फ़ाइल नहीं चलेगी। मॉडल ड्रॉइंग के साथ सेव होता है; Properties में scale, rotation और ऊँचाई।</li><li><b>एक्सपोर्ट:</b> File → <i>Export 3D model — GLB</i> (Windows 3D Viewer, Blender, ऑनलाइन viewer), <i>OBJ + MTL</i> (zip), <i>Export BIM model — IFC4</i> (Revit, ArchiCAD, IFC viewer) — मंज़िल, एलिमेंट के प्रकार, रंग और एस्टीमेट वाली मात्राएँ साथ। IFC में आकार त्रिकोणों से बने होते हैं (दूसरे सॉफ़्टवेयर में parametric दीवार की तरह edit नहीं होंगे); ओपनिंग दीवार में कटी रहती है।</li></ul>" }
    ] },
    { id: "gcam", t: { en: "18C. GPS Photos — camera with location stamp (kept 45 days)", hi: "18C. GPS Photos — लोकेशन वाली फ़ोटो (45 दिन तक)" }, b: [
      { en: "<ul><li>Tap <b>📷</b> at the top or open the <b>GPS Photos</b> tab → <i>Take GPS photo</i>. Allow <b>camera</b> and <b>location</b> when the phone asks. The photos are your own album — they are <b>not</b> added to any estimate.</li><li>Wait for the <b>green dot</b> (GPS ±20 m or better). Type the site / place name (remembered for the next photos) and a note, then press the round button. <i>📁 Phone camera</i> opens the phone's own camera app instead.</li><li>Each photo is stamped with place and address, latitude–longitude, accuracy, altitude, date-time (IST), site name, note and a small map. Location and time are also written inside the JPG (EXIF).</li><li>No network at site: the photo is still taken with coordinates, kept on the phone and uploaded later by itself.</li><li><b>GPS Photos</b> tab: photos are grouped by date. Tick photos (or a whole day, or <i>Select all</i>) and <i>Download</i> (one JPG, or a ZIP for many), <i>Share</i> (WhatsApp etc.), <i>Photo sheet</i> for print / PDF, or <i>Delete</i>. Search by site, note, place or date.</li><li><b>⚠ Photos are deleted automatically 45 days after they are taken.</b> Each photo shows how many days are left; the tab gets an orange dot when photos will be deleted within 7 days (<i>Select these</i> picks them). Download what you need to your computer in time.</li><li>The super admin runs <code>supabase/photos.sql</code> once so photos are kept online; until then they stay on the phone.</li></ul>",
        hi: "<ul><li>ऊपर <b>📷</b> दबाएँ या <b>GPS Photos</b> टैब → <i>Take GPS photo</i>। फ़ोन पूछे तो <b>कैमरा</b> और <b>लोकेशन</b> की अनुमति दें। ये आपका अलग फ़ोटो एल्बम है — फ़ोटो किसी एस्टीमेट में <b>नहीं</b> जुड़ती।</li><li><b>हरा बिंदु</b> (GPS ±20 मी या बेहतर) आने दें। साइट / जगह का नाम (अगली फ़ोटो के लिए याद रहता है) और टिप्पणी लिखें, फिर गोल बटन दबाएँ। <i>📁 Phone camera</i> से फ़ोन का अपना कैमरा खुलता है।</li><li>हर फ़ोटो पर जगह और पता, अक्षांश–देशांतर, सटीकता, ऊँचाई, तारीख-समय (IST), साइट का नाम, टिप्पणी और छोटा नक्शा छपता है। लोकेशन और समय JPG फ़ाइल के अंदर (EXIF) भी रहता है।</li><li>साइट पर नेटवर्क न हो तो भी फ़ोटो निर्देशांक के साथ खिंचती है, फ़ोन में रहती है और बाद में अपने आप अपलोड हो जाती है।</li><li><b>GPS Photos</b> टैब: फ़ोटो तारीख के हिसाब से दिखती हैं। फ़ोटो (या पूरा दिन, या <i>Select all</i>) चुनकर <i>Download</i> (एक JPG या कई हों तो ZIP), <i>Share</i> (WhatsApp आदि), <i>Photo sheet</i> (प्रिंट / PDF) या <i>Delete</i> करें। साइट, टिप्पणी, जगह या तारीख से खोजें।</li><li><b>⚠ फ़ोटो खींचने के 45 दिन बाद अपने आप डिलीट हो जाती हैं।</b> हर फ़ोटो पर बचे दिन दिखते हैं; 7 दिन में डिलीट होने वाली फ़ोटो हों तो टैब पर नारंगी बिंदु आता है (<i>Select these</i> से वे चुनी जाती हैं)। ज़रूरी फ़ोटो समय रहते अपने कंप्यूटर में डाउनलोड कर लें।</li><li>फ़ोटो ऑनलाइन रखने के लिए सुपर एडमिन एक बार <code>supabase/photos.sql</code> चलाए; तब तक फ़ोटो फ़ोन में ही रहती हैं।</li></ul>" } ] },
    { id: "offline", t: { en: "18D. Install on the phone and work without network", hi: "18D. फ़ोन में इंस्टॉल करें और बिना नेटवर्क काम करें" }, b: [
      { en: "<ul><li><b>Install:</b> open the site in Chrome on the phone, tap <i>Install app</i> at the top (or Chrome menu ⋮ → <i>Add to Home screen / Install app</i>). On iPhone: Safari → Share → <i>Add to Home Screen</i>.</li><li>Open the app once with network after signing in, so the rate books are kept on the phone.</li><li><b>Without network</b> (mines, remote sites): a yellow bar says so. Open your estimates, add items and measurements — every change is <i>Saved on this device</i>. New estimates can also be made.</li><li>When the network returns, changes are sent to the server by themselves (blue bar shows the count waiting). If somebody changed the same estimate on the server meanwhile, the server copy is kept as a version first, so nothing is lost.</li><li>Things that need the server (send for review, users, backup) ask for network.</li></ul>",
        hi: "<ul><li><b>इंस्टॉल:</b> फ़ोन के Chrome में साइट खोलें, ऊपर <i>Install app</i> दबाएँ (या Chrome मेनू ⋮ → <i>Add to Home screen / Install app</i>)। iPhone पर: Safari → Share → <i>Add to Home Screen</i>।</li><li>लॉगिन के बाद एक बार नेटवर्क में ऐप खोलें ताकि रेट बुक फ़ोन में रख ली जाएँ।</li><li><b>बिना नेटवर्क</b> (खदान, दूर की साइट): पीली पट्टी दिखती है। एस्टीमेट खोलें, आइटम और नाप जोड़ें — हर बदलाव <i>Saved on this device</i> होता है। नया एस्टीमेट भी बना सकते हैं।</li><li>नेटवर्क आते ही बदलाव अपने आप सर्वर पर चले जाते हैं (नीली पट्टी में बाकी संख्या दिखती है)। अगर इस बीच किसी ने वही एस्टीमेट सर्वर पर बदला हो तो सर्वर वाली कॉपी पहले वर्ज़न के रूप में रख ली जाती है, कुछ खोता नहीं।</li><li>सर्वर वाले काम (review भेजना, users, backup) के लिए नेटवर्क चाहिए।</li></ul>" } ] },
    { id: "backup", t: { en: "19. Backup and restore", hi: "19. बैकअप और रिस्टोर" }, b: [
      { en: "<ul><li><b>What can be lost?</b> Rate books, SORs, analyses, suggested items and the Design Studio are part of the app. Your <i>own work</i> (estimates, personal rates, NS library, uploaded SORs) is kept on the server, so keep a copy too.</li><li><b>Download:</b> open the <i>Backup</i> tab and click <i>Download my backup</i>. Keep the .json file in Google Drive, email or a pen drive. An orange dot on the tab means your last backup is more than 7 days old.</li><li><b>Restore:</b> <i>Backup</i> tab, choose the file, tick what to restore, click <i>Restore now</i>. Nothing is deleted and items already present are skipped, so running it twice is safe.</li><li><b>Super admin:</b> <i>Download full backup (all users)</i> saves everyone's work, roles and licences. Restoring it puts each person's work back into their account (matched by email) once they have signed up.</li></ul>",
        hi: "<ul><li><b>क्या खो सकता है?</b> रेट बुक, SOR, analysis, suggested items और Design Studio ऐप का हिस्सा हैं। आपका <i>अपना काम</i> (एस्टीमेट, अपने रेट, NS लाइब्रेरी, अपलोड SOR) सर्वर पर रहता है, इसलिए उसकी कॉपी भी रखें।</li><li><b>डाउनलोड:</b> <i>Backup</i> टैब खोलें और <i>Download my backup</i> दबाएँ। .json फाइल Google Drive, ईमेल या पेन ड्राइव में रखें। टैब पर नारंगी बिंदु का मतलब है पिछला बैकअप 7 दिन से पुराना है।</li><li><b>रिस्टोर:</b> <i>Backup</i> टैब में फाइल चुनें, क्या वापस लाना है टिक करें, <i>Restore now</i> दबाएँ। कुछ भी डिलीट नहीं होता, जो पहले से है वह छोड़ दिया जाता है, इसलिए दो बार चलाना भी सुरक्षित है।</li><li><b>सुपर एडमिन:</b> <i>Download full backup (all users)</i> सबका काम, role और licence सेव करता है। रिस्टोर करने पर हर व्यक्ति का काम उसके अकाउंट में (ईमेल से मिलाकर) वापस आता है, जब वह दोबारा साइन अप कर ले।</li></ul>" }
    ] },
    { id: "faq", t: { en: "20. Tips and common questions", hi: "20. सुझाव और आम सवाल" }, b: [
      { en: "<ul><li><b>Signed out suddenly?</b> Your account signed in on another computer. Sign in again here.</li><li><b>Rate looks different from the SOR?</b> The updated rate uses today's basic rates. Choose <i>SOR rate</i> in Header, parts &amp; GST if your office wants the printed rate.</li><li><b>Item not found?</b> Try fewer words, the code, or a site word; or create an NS item.</li><li><b>Need help or activation?</b> Sales: presidentsri@live.com · 7400501000. Developer: prashantmahto2819@gmail.com.</li><li><b>Translate:</b> this page is in English and हिंदी — use the switch at the top. Your browser's translate option also works.</li></ul>",
        hi: "<ul><li><b>अचानक लॉगआउट हो गए?</b> आपका अकाउंट किसी दूसरे कंप्यूटर पर लॉगिन हुआ है। यहाँ दोबारा लॉगिन करें।</li><li><b>रेट SOR से अलग है?</b> Updated रेट आज के basic rates से बनता है। अगर कार्यालय में छपा रेट चाहिए तो Header, parts &amp; GST में <i>SOR rate</i> चुनें।</li><li><b>आइटम नहीं मिल रहा?</b> कम शब्द, कोड या साइट वाला शब्द लिखें; या NS आइटम बनाएँ।</li><li><b>मदद या activation चाहिए?</b> Sales: presidentsri@live.com · 7400501000। Developer: prashantmahto2819@gmail.com।</li><li><b>भाषा:</b> यह पेज English और हिंदी दोनों में है — ऊपर के बटन से बदलें। ब्राउज़र का translate विकल्प भी चलता है।</li></ul>" },
    ] },
  ];

  U.views.help = function () {
    var L = S.help.lang, esc = U.esc;
    var h = '<div class="help"><aside class="help-toc panel"><div class="lbl">' + (L === "hi" ? "विषय सूची" : "Contents") + "</div>" + SEC.map(function (s) { return '<a href="#help-' + s.id + '" data-helpgo="' + s.id + '">' + esc(s.t[L]) + "</a>"; }).join("") + "</aside><article class='help-body'>";
    h += '<div class="help-top"><div><h1>' + (L === "hi" ? "Estimate Pro कैसे चलाएँ — पूरा ट्यूटोरियल" : "How to use Estimate Pro — complete tutorial") + '</h1><p class="muted" style="margin:0">' + (L === "hi" ? "स्क्रीनशॉट के साथ हर विकल्प की जानकारी। भाषा बदलने के लिए दाईं ओर का बटन दबाएँ।" : "Every option explained with screenshots. Use the switch on the right to change language.") + '</p></div><div class="seg" role="group" aria-label="Language"><button type="button" data-helplang="hi" aria-pressed="' + (L === "hi") + '">हिंदी</button><button type="button" data-helplang="en" aria-pressed="' + (L === "en") + '">English</button></div></div>';
    SEC.forEach(function (s) {
      h += '<section class="help-sec panel" id="help-' + s.id + '"><h2>' + esc(s.t[L]) + "</h2>";
      s.b.forEach(function (b) {
        if (b.img) h += '<figure><img loading="lazy" src="help/' + b.img + '" alt="' + esc(b.cap[L]) + '"><figcaption>' + esc(b.cap[L]) + "</figcaption></figure>";
        else h += b[L];
      });
      h += "</section>";
    });
    return h + "</article></div>";
  };
  document.addEventListener("click", function (e) {
    var t = e.target.closest && e.target.closest("[data-helplang],[data-helpgo]"); if (!t) return;
    if (t.dataset.helplang) { S.help.lang = t.dataset.helplang; setLang(S.help.lang); U.render(); return; }
    if (t.dataset.helpgo) { e.preventDefault(); var n = document.getElementById("help-" + t.dataset.helpgo); if (n) n.scrollIntoView({ behavior: "smooth", block: "start" }); }
  });
})();
